/**
 * Separate balanced parenthesis groups from a string.
 *
 * @param {string} paren_string - Input string containing multiple groups of nested parentheses.
 * @returns {string[]} An array of the separated parenthesis groups.
 */
const separateParenGroups = (paren_string) => {
  // Remove all whitespace characters.
  const cleaned = paren_string.replace(/\s+/g, '');

  const groups = [];
  let depth = 0;
  let current = '';

  for (const ch of cleaned) {
    if (ch === '(') {
      // Start a new group when depth goes from 0 to 1.
      if (depth === 0) current = '';
      current += ch;
      depth++;
    } else if (ch === ')') {
      depth--;
      current += ch;
      // When depth returns to 0, we have a complete group.
      if (depth === 0) {
        groups.push(current);
        current = '';
      }
    }
    // Any other characters are ignored (the problem guarantees only parentheses).
  }

  return groups;
};
```

