 * Split a string of nested parentheses into separate balanced groups.
 *
 * @param {string} paren_string - Input string containing groups of parentheses separated by spaces.
 * @returns {string[]} Array of balanced parenthesis groups without spaces.
 */
const separateParenGroups = (paren_string) => {
  const groups = [];
  let buffer = '';
  let depth = 0;

  for (const ch of paren_string) {
    if (ch === ' ') continue;          // ignore spaces

    if (ch === '(' || ch === ')') {
      buffer += ch;                    // accumulate the parenthesis

      if (ch === '(') {
        depth += 1;
      } else {
