/**
 * Compute the maximum depth of nested parentheses for each group in a string.
 *
 * @param {string} paren_string - A string containing groups of parentheses separated by spaces.
 * @returns {number[]} An array of maximum depths for each group.
 */
const parseNestedParens = (paren_string) => {
  // Split on whitespace, ignoring any empty segments
  const groups = paren_string.trim().split(/\s+/).filter(Boolean);

  return groups.map((group) => {
    let depth = 0;
    let maxDepth = 0;

    for (const ch of group) {
      if (ch === '(') {
        depth += 1;
        if (depth > maxDepth) maxDepth = depth;
      } else if (ch === ')') {
        depth -= 1;
      }
    }

    return maxDepth;
  });
};
```

