/**
 * Returns the shortest palindrome that starts with the given string.
 * The algorithm finds the longest palindromic suffix of the input string
 * and appends the reverse of the preceding prefix.
 *
 * @param {string} str - The input string.
 * @returns {string} The shortest palindrome beginning with `str`.
 */
const makePalindrome = (str) => {
  // Helper to check if a string is a palindrome
  const isPalindrome = (s) => {
    const len = s.length;
    for (let i = 0; i < len / 2; i++) {
      if (s[i] !== s[len - 1 - i]) return false;
    }
    return true;
  };

  // Find the longest palindromic suffix
  let suffixStart = 0; // index where the suffix starts
  for (let i = 0; i < str.length; i++) {
    const suffix = str.slice(i);
    if (isPalindrome(suffix)) {
      suffixStart = i;
      break;
    }
  }

  const prefix = str.slice(0, suffixStart);
  const reversedPrefix = prefix.split('').reverse().join('');
  return str + reversedPrefix;
};
