/**
 * Perform a bitwise XOR on two binary strings.
 *
 * @param {string} a - First binary string (consisting of '0' and '1').
 * @param {string} b - Second binary string (consisting of '0' and '1').
 * @returns {string} The XOR result as a binary string.
 */
const stringXor = (a, b) => {
  // Pad the shorter string with leading zeros so both have the same length.
  const maxLen = Math.max(a.length, b.length);
  const padA = a.padStart(maxLen, '0');
  const padB = b.padStart(maxLen, '0');

  let result = '';
  for (let i = 0; i < maxLen; i++) {
    // Convert characters to booleans and XOR them.
    const xorBit = (padA[i] === '1') ^ (padB[i] === '1');
    result += xorBit ? '1' : '0';
  }

  // Remove leading zeros but keep at least one digit.
  return result.replace(/^0+/, '') || '0';
};
