/**
 * Returns the longest string in an array.
 * If multiple strings share the maximum length, the first one is returned.
 * Returns null if the array is empty.
 *
 * @param {string[]} strings - Array of strings to search.
 * @returns {string|null} The longest string or null.
 */
const longest = (strings) => {
  if (!Array.isArray(strings) || strings.length === 0) return null;

  // Use reduce to keep the first string when lengths are equal
  return strings.reduce((best, current) =>
    current.length > best.length ? current : best
  );
};
