/**
 * Returns the greatest common divisor (GCD) of two integers a and b.
 * Uses the Euclidean algorithm and works for negative inputs.
 *
 * @param {number} a - First integer
 * @param {number} b - Second integer
 * @returns {number} The greatest common divisor of a and b
 */
const greatestCommonDivisor = (a, b) => {
  // Handle the special case where both numbers are zero
  if (a === 0 && b === 0) return 0;

  // Work with absolute values to avoid negative remainders
  a = Math.abs(a);
  b = Math.abs(b);

  // Euclidean algorithm
  while (b !== 0) {
    const temp = b;
    b = a % b;
    a = temp;
  }

  return a;
};
```

