/**
 * Returns true if any two numbers in the array are closer to each other
 * than the given threshold.
 *
 * @param {number[]} numbers - Array of numeric values.
 * @param {number} threshold - The distance threshold.
 * @returns {boolean} - True if a pair of numbers is closer than threshold, otherwise false.
 */
const hasCloseElements = (numbers, threshold) => {
  if (!Array.isArray(numbers) || numbers.length < 2) return false;

  // Work on a sorted copy to avoid mutating the original array
  const sorted = [...numbers].sort((a, b) => a - b);

  for (let i = 1; i < sorted.length; i++) {
    if (Math.abs(sorted[i] - sorted[i - 1]) < threshold) {
      return true;
    }
  }
  return false;
};
```

