 * @param {string} music_string - The ASCII representation of the music.
 * @returns {number[]} Array of beat counts for each note.
 */
const parseMusic = (music_string) => {
  if (!music_string) return [];

  // Split on any whitespace (spaces, tabs, newlines)
  const tokens = music_string.trim().split(/\s+/);

  const beatsMap = {
    'o': 4,
    'o|': 2,
    '.|': 1,
  };

  const result = [];

  for (const token of tokens) {
    if (token in beatsMap) {
      result.push(beatsMap[token]);
    } else {
      // If an unexpected token is encountered, ignore it or throw an error.
      // Here we simply ignore it to keep the function tolerant.
      continue;
    }
  }

  return result;
};

