const howManyTimes = (string, substring) => {
  // If either string is empty or substring is longer than the string,
  // there can be no matches.
  if (!string || !substring || substring.length > string.length) {
    return 0;
  }

  let count = 0;
  let start = 0;

  while (true) {
    const pos = string.indexOf(substring, start);
    if (pos === -1) break;          // no more occurrences
    count++;
    start = pos + 1;                // allow overlapping by moving only one step
  }

  return count;
};
