  if (!numbers || !numbers.trim()) return '';

  // Split, map to numbers, sort, map back to words
  return numbers
    .trim()
    .split(/\s+/)
    .map((w) => wordToNum[w])
    .sort((a, b) => a - b)
    .map((n) => numToWord[n])
