/**
 * Rescales an array of numbers to the unit interval [0, 1].
 *
 * The smallest value in the input becomes 0, the largest becomes 1,
 * and all other values are linearly interpolated between them.
 *
 * @param {number[]} numbers - Array of at least two numeric values.
 * @returns {number[]} A new array with each element rescaled to [0, 1].
 * @throws {Error} If the input is not an array or contains fewer than two elements.
 */
const rescaleToUnit = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length < 2) {
    throw new Error('Input must be an array of at least two numbers');
  }

  // Find the minimum and maximum values
  const { min, max } = numbers.reduce(
    (acc, n) => ({
      min: Math.min(acc.min, n),
      max: Math.max(acc.max, n),
    }),
    { min: Infinity, max: -Infinity }
  );

  // If all numbers are identical, return an array of zeros
  if (min === max) {
    return numbers.map(() => 0);
  }

  const range = max - min;

  // Apply the linear transformation
  return numbers.map((n) => (n - min) / range);
};
```

