/**
 * Returns the largest divisor of `n` that is strictly smaller than `n`.
 * For prime numbers the result is 1. For n <= 1 the function returns 1.
 *
 * @param {number} n - The number to find the divisor for.
 * @returns {number} The largest divisor of `n` that is < n.
 */
const largestDivisor = (n) => {
  const absN = Math.abs(n);

  // Edge cases: 0 or 1 have no proper divisor, return 1 by convention
  if (absN <= 1) return 1;

  // Find the smallest divisor greater than 1
  const limit = Math.floor(Math.sqrt(absN));
  for (let i = 2; i <= limit; i++) {
    if (absN % i === 0) {
      // The largest divisor smaller than n is n / smallestDivisor
      return absN / i;
    }
  }

  // If no divisor found, n is prime
  return 1;
};
```

