/**
 * Returns the largest integer that divides `n` evenly and is smaller than `n`.
 * For prime numbers the result is 1. If `n` is 0 or 1, the function returns null.
 *
 * @param {number} n - The number to find the largest divisor for.
 * @returns {number|null} The largest divisor of `n` that is < `n`, or null for n <= 1.
 */
const largestDivisor = (n) => {
  if (n <= 1) return null;          // No proper divisor exists for 0 or 1

  // Start from the largest possible proper divisor (n/2) and work downwards.
  for (let i = Math.floor(n / 2); i >= 1; i--) {
    if (n % i === 0) return i;      // First match is the largest divisor
  }

  // Fallback – should never be reached because 1 always divides n.
  return 1;
};
```

