/**
 * Return the prime factorization of a positive integer `n` as an array
 * of prime factors sorted from smallest to largest. Each factor appears
 * as many times as it occurs in the factorization.
 *
 * @param {number} n - The integer to factorize (n >= 2).
 * @returns {number[]} Array of prime factors in ascending order.
 */
const factorize = (n) => {
  if (n < 2) return []; // no prime factors for 0, 1 or negative numbers

  const factors = [];
  let num = n;

  // Handle factor 2 separately to allow skipping even numbers later
  while (num % 2 === 0) {
    factors.push(2);
    num /= 2;
  }

  // Check odd divisors from 3 up to sqrt(num)
  for (let i = 3; i * i <= num; i += 2) {
    while (num % i === 0) {
      factors.push(i);
      num /= i;
    }
  }

  // If remaining num is a prime greater than 2
  if (num > 1) {
    factors.push(num);
  }

  return factors;
};
```

