/**
 * Remove all elements that occur more than once from an array.
 * The relative order of the remaining elements is preserved.
 *
 * @param {number[]} numbers - The input array of integers.
 * @returns {number[]} A new array containing only the elements that appear exactly once.
 */
const removeDuplicates = (numbers) => {
  // Count occurrences of each number
  const freq = new Map();
  for (const n of numbers) {
    freq.set(n, (freq.get(n) || 0) + 1);
  }

  // Filter out numbers that appear more than once
  return numbers.filter((n) => freq.get(n) === 1);
};
```

