const flipCase = (string) => {
  // Convert each character: if it's uppercase, make it lowercase; otherwise, make it uppercase.
  // Non-letter characters remain unchanged because toUpperCase()/toLowerCase() return the same char.
  return string.split('').map(ch => (ch === ch.toUpperCase() ? ch.toLowerCase() : ch.toUpperCase())).join('');
};
