/**
 * Returns a new array containing only the strings that start with the given prefix.
 *
 * @param {string[]} strings - The array of strings to filter.
 * @param {string} prefix   - The prefix to match.
 * @returns {string[]} A new array with strings that begin with `prefix`.
 */
const filterByPrefix = (strings, prefix) => {
  if (!Array.isArray(strings) || typeof prefix !== 'string') return [];
  return strings.filter(str => typeof str === 'string' && str.startsWith(prefix));
};
