const sortThird = (l) => {
  // Collect indices divisible by 3 and their corresponding values
  const indices = [];
  const values = [];
  for (let i = 0; i < l.length; i++) {
    if (i % 3 === 0) {
      indices.push(i);
      values.push(l[i]);
    }
  }

  // Sort the collected values numerically
  values.sort((a, b) => a - b);

  // Build the result array, preserving non‑divisible indices
  const result = l.slice(); // shallow copy of the original array
  for (let k = 0; k < indices.length; k++) {
    result[indices[k]] = values[k];
  }

  return result;
};
