// Find one real root of an odd‑degree polynomial (even number of coefficients)
// Assumes the polynomial has at least one real root.
const findZero = (xs) => {
  // Evaluate polynomial at x using Horner's method
  const poly = (x) => {
    let result = 0;
    for (let i = xs.length - 1; i >= 0; i--) {
      result = result * x + xs[i];
    }
    return result;
  };

  // If zero is exactly at 0
  if (poly(0) === 0) return 0;

  // Find interval [a, b] where the polynomial changes sign
  let a = 0, b = 1;
  let fa = poly(a), fb = poly(b);
  let step = 1;
  while (fa * fb > 0) {
    a -= step;
    b += step;
    fa = poly(a);
    fb = poly(b);
    step *= 2;
    // Safety guard to avoid infinite loop
    if (step > 1e12) break;
  }

  // Bisection method to refine the root
  const eps = 1e-12;
  let left = a, right = b, mid, fmid;
  while (right - left > eps) {
    mid = (left + right) / 2;
    fmid = poly(mid);
    if (fmid === 0) return mid;
    if (fa * fmid <= 0) {
      right = mid;
      fb = fmid;
    } else {
      left = mid;
      fa = fmid;
    }
  }
  return (left + right) / 2;
};
```

