/**
 * Evaluate a polynomial at a given point using Horner's method.
 * @param {number[]} coeffs - Coefficients of the polynomial (constant term first).
 * @param {number} x - The point at which to evaluate.
 * @returns {number} The polynomial value at x.
 */
const evalPoly = (coeffs, x) => {
  let result = 0;
  for (let i = coeffs.length - 1; i >= 0; i--) {
    result = result * x + coeffs[i];
  }
  return result;
};

/**
 * Find a real root of a polynomial with an odd degree.
 * The input array must contain an even number of coefficients,
 * and the highest non‑zero coefficient guarantees a real root.
 *
 * @param {number[]} xs - Coefficients of the polynomial (constant term first).
 * @returns {number} A real root of the polynomial.
 */
const findZero = (xs) => {
  // Find the highest non‑zero coefficient index
  let highest = xs.length - 1;
  while (highest >= 0 && xs[highest] === 0) highest--;
  if (highest < 0) throw new Error('Zero polynomial has no roots');

  // Helper to evaluate polynomial
  const f = (x) => evalPoly(xs, x);

  // Find an interval [low, high] where f(low) and f(high) have opposite signs
  let low = -1, high = 1;
  let fLow = f(low), fHigh = f(high);
  const maxIter = 1000;
  let iter = 0;
  while (fLow * fHigh > 0 && iter < maxIter) {
    // Expand the interval exponentially
    low *= 2;
    high *= 2;
    fLow = f(low);
    fHigh = f(high);
    iter++;
  }
  if (iter === maxIter) throw new Error('Failed to bracket a root');

  // Bisection method
  const eps = 1e-12;
  while (high - low > eps) {
    const mid = (low + high) / 2;
    const fMid = f(mid);
    if (fMid === 0) return mid;
    if (fLow * fMid <= 0) {
      high = mid;
      fHigh = fMid;
    } else {
      low = mid;
      fLow = fMid;
    }
  }
  return (low + high) / 2;
};
