const sortThird = (l) => {
  // Create a shallow copy so the original array is not mutated
  const result = l.slice();

  // Collect indices divisible by 3 and their corresponding values
  const indices = [];
  const values = [];
  for (let i = 0; i < l.length; i++) {
    if (i % 3 === 0) {
      indices.push(i);
      values.push(l[i]);
    }
  }

  // Sort the collected values numerically
  values.sort((a, b) => a - b);

  // Place the sorted values back into the result array at the same indices
  for (let k = 0; k < indices.length; k++) {
    result[indices[k]] = values[k];
  }

  return result;
};
