// Helper: modular exponentiation (base^exp mod mod) for BigInt
const modPow = (base, exp, mod) => {
  let result = 1n;
  base = base % mod;
  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    exp >>= 1n;
  }
  return result;
};

// Miller–Rabin primality test for BigInt (deterministic for n < 2^64)
const isPrimeBigInt = (n) => {
  if (n < 2n) return false;
  // small primes
  const smallPrimes = [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n];
  for (const p of smallPrimes) {
    if (n === p) return true;
    if (n % p === 0n) return false;
  }

  // write n-1 as d * 2^s
  let d = n - 1n;
  let s = 0n;
  while ((d & 1n) === 0n) {
    d >>= 1n;
    s++;
  }

  // deterministic bases for 64-bit integers
  const bases = [2n, 325n, 9375n, 28178n, 450775n, 9780504n, 1795265022n];
  for (const a of bases) {
    if (a % n === 0n) continue;
    let x = modPow(a, d, n);
    if (x === 1n || x === n - 1n) continue;
    let continueOuter = false;
    for (let r = 1n; r < s; r++) {
      x = (x * x) % n;
      if (x === n - 1n) {
        continueOuter = true;
        break;
      }
    }
    if (continueOuter) continue;
    return false;
  }
  return true;
};

// Main function: nth Fibonacci number that is also prime
const primeFib = (n) => {
  if (n < 1) throw new Error('n must be >= 1');
  let count = 0;
  let a = 0n, b = 1n; // Fibonacci sequence
  while (true) {
    const fib = a;
    a = b;
    b = fib + a;
    if (fib > 1n && isPrimeBigInt(fib)) {
      count++;
      if (count === n) return fib;
    }
  }
};
