const isPrimeBigInt = (n) => {
  if (n < 2n) return false;
  if (n === 2n || n === 3n) return true;
  if (n % 2n === 0n) return false;

  // Small prime trial division
  const smallPrimes = [
    3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n,
  ];
  for (const p of smallPrimes) {
    if (n === p) return true;
    if (n % p === 0n) return false;
  }

  // Write n-1 as d * 2^s
  let d = n - 1n;
  let s = 0n;
  while (d % 2n === 0n) {
    d /= 2n;
    s++;
  }

  // Deterministic bases for 64‑bit integers
  const bases = [
    2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n,
  ];

  for (const a of bases) {
    if (a >= n) continue;
    let x = modPow(a, d, n);
    if (x === 1n || x === n - 1n) continue;
    let composite = true;
    for (let r = 1n; r < s; r++) {
      x = (x * x) % n;
      if (x === n - 1n) {
        composite = false;
        break;
      }
    }
    if (composite) return false;
  }
  return true;
};

// Main function: nth Fibonacci number that is also prime
const primeFib = (n) => {
  if (n < 1) throw new Error('n must be a positive integer');
  let count = 0;
  let a = 0n, b = 1n; // Fibonacci seeds
  while (true) {
    const c = a + b; // next Fibonacci number
    a = b;
    b = c;
    if (isPrimeBigInt(c)) {
      count++;
      if (count === n) return c;
    }
  }
};

