/**
 * Decodes a string that was encoded with the `encode_cyclic` function.
 *
 * The encoding algorithm shifts each alphabetic character by a value
 * derived from its position in the string:
 *   shift = Math.floor(index * index / 2)  (index is 0‑based)
 * The shift is applied cyclically within the alphabet (A‑Z or a‑z).
 *
 * Non‑alphabetic characters are left unchanged.
 *
 * @param {string} s - The encoded string.
 * @returns {string} The decoded string.
 */
const decodeCyclic = (s) => {
  let result = '';

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = ch.charCodeAt(0);
    const shift = Math.floor(i * i / 2) % 26; // shift amount for this position

    // Uppercase letters
    if (code >= 65 && code <= 90) {
      const base = 65;
      const decodedCode = ((code - base - shift + 26) % 26) + base;
      result += String.fromCharCode(decodedCode);
    }
    // Lowercase letters
    else if (code >= 97 && code <= 122) {
      const base = 97;
      const decodedCode = ((code - base - shift + 26) % 26) + base;
      result += String.fromCharCode(decodedCode);
    }
    // Non‑alphabetic characters remain unchanged
    else {
      result += ch;
    }
  }

  return result;
};
