/**
 * Returns true if there exist three distinct elements in the array that sum to zero.
 * @param {number[]} l - Array of integers.
 * @returns {boolean}
 */
const triplesSumToZero = (l) => {
  const n = l.length;
  if (n < 3) return false;

  // Sort the array to enable two‑pointer technique
  const nums = [...l].sort((a, b) => a - b);

  for (let i = 0; i < n - 2; i++) {
    // Skip duplicate values for the first element to reduce work
    if (i > 0 && nums[i] === nums[i - 1]) continue;

    let left = i + 1;
    let right = n - 1;

    while (left < right) {
      const sum = nums[i] + nums[left] + nums[right];
      if (sum === 0) return true;
      if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
};
```

