/**
 * Calculates the total number of collisions between two sets of cars
 * moving in opposite directions on an infinite straight line.
 *
 * All cars move at the same speed and are initially far apart, so each
 * left‑to‑right car will collide exactly once with each right‑to‑left car.
 * Therefore the total number of collisions is n * n.
 *
 * @param {number} n - The number of cars in each direction (non‑negative integer).
 * @returns {bigint} The total number of collisions as a BigInt.
 */
const carRaceCollision = (n) => {
  if (typeof n !== 'number' || !Number.isInteger(n) || n < 0) {
    throw new TypeError('n must be a non‑negative integer');
  }
  const bigN = BigInt(n);
  return bigN * bigN;
};
