/**
 * Convert a non‑negative integer `x` to a string representation in the given `base`.
 * The base must be an integer less than 10.
 *
 * @param {number} x - The number to convert (non‑negative integer).
 * @param {number} base - The target base (integer < 10).
 * @returns {string} The string representation of `x` in the specified base.
 */
const changeBase = (x, base) => {
  if (x === 0) return '0';
  if (base < 2 || base >= 10) {
    throw new Error('Base must be an integer between 2 and 9 inclusive.');
  }

  let digits = [];
  let n = x;

  while (n > 0) {
    const digit = n % base;
    digits.push(digit.toString());
    n = Math.floor(n / base);
  }

  return digits.reverse().join('');
};
```

