 * Computes the n-th element of the Fib4 sequence.
 *
 * Definition:
 *   fib4(0) = 0
 *   fib4(1) = 0
 *   fib4(2) = 2
 *   fib4(3) = 0
 *   fib4(n) = fib4(n-1) + fib4(n-2) + fib4(n-3) + fib4(n-4)   for n >= 4
 *
 * The implementation uses an iterative approach with constant space.
 *
 * @param {number} n - The index of the desired Fib4 number (non‑negative integer).
 * @returns {number} The n-th Fib4 number.
 */
const fib4 = (n) => {
  if (n < 0) return 0;          // optional guard for negative indices

  // Handle the base cases directly
  switch (n) {
    case 0: return 0;
    case 1: return 0;
    case 2: return 2;
    case 3: return 0;
  }

  // Initialize the last four values
  let a = 0; // fib4(n-4)
  let b = 0; // fib4(n-3)
  let c = 2; // fib4(n-2)
  let d = 0; // fib4(n-1)

  // Iterate from 4 up to n, updating the sliding window
  for (let i = 4; i <= n; i++) {
    const next = a + b + c + d; // fib4(i)
    a = b; // shift window
    b = c;
    c = d;
    d = next;
  }

  return d; // d holds fib4(n) after the loop
};
```

