  let prev4 = 0; // fib4(n-4)
  let prev3 = 0; // fib4(n-3)
  let prev2 = 2; // fib4(n-2)
  let prev1 = 0; // fib4(n-1)

  let current = 0;

  for (let i = 4; i <= n; i++) {
    current = prev1 + prev2 + prev3 + prev4; // fib4(i)
    // Shift the window for the next iteration
    prev4 = prev3;
    prev3 = prev2;
    prev2 = prev1;
    prev1 = current;
  }

