/**
 * Returns the median of an array of numbers.
 * For an odd-length array, the middle element after sorting is returned.
 * For an even-length array, the average of the two middle elements is returned.
 *
 * @param {number[]} l - The array of numbers.
 * @returns {number|null} The median value, or null if the array is empty or not an array.
 */
const median = (l) => {
  if (!Array.isArray(l) || l.length === 0) return null;

  // Create a sorted copy of the array (numeric sort)
  const sorted = [...l].sort((a, b) => a - b);

  const mid = Math.floor(sorted.length / 2);

  // Odd length: return the middle element
  if (sorted.length % 2 !== 0) {
    return sorted[mid];
  }

  // Even length: return the average of the two middle elements
  return (sorted[mid - 1] + sorted[mid]) / 2;
};
```

