/**
 * Compute 2^n modulo p using fast modular exponentiation.
 * Works for large n and p by using BigInt for intermediate calculations.
 *
 * @param {number|bigint} n - exponent (non‑negative integer)
 * @param {number|bigint} p - modulus (positive integer)
 * @returns {number} 2^n mod p as a normal JavaScript number
 */
const modp = (n, p) => {
  // Convert inputs to BigInt for safe arithmetic
  const exp = BigInt(n);
  const mod = BigInt(p);

  // Edge case: modulus 1 → result is always 0
  if (mod === 1n) return 0;

  let base = 2n % mod;   // base = 2 mod p
  let result = 1n;

  let e = exp;
  while (e > 0n) {
    if (e & 1n) {
      result = (result * base) % mod;
    }
    base = (base * base) % mod;
    e >>= 1n;
  }

  // Convert back to Number (safe because result < p)
  return Number(result);
};
