/**
 * Compute 2^n modulo p using fast modular exponentiation.
 * Works for arbitrarily large n and p by using BigInt.
 *
 * @param {number|bigint} n - exponent (non‑negative)
 * @param {number|bigint} p - modulus (positive)
 * @returns {number} 2^n mod p (as a Number if it fits in safe integer range)
 */
const modp = (n, p) => {
  const exp = BigInt(n);
  const mod = BigInt(p);

  if (mod === 0n) throw new Error('modulo by zero');

  let result = 1n;
  let base = 2n % mod;
  let e = exp;

  while (e > 0n) {
    if (e & 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    e >>= 1n;
  }

  // Return as Number if it is within safe integer range, otherwise as BigInt
  return result <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(result) : result;
};

