/**
 * Decodes a string that was encoded with a simple shift cipher.
 * The original `encode_shift` function is assumed to shift every
 * character forward by one position in the ASCII table.
 *
 * @param {string} s - The encoded string.
 * @returns {string} The decoded string.
 */
const decodeShift = (s) => {
  // Helper to shift a single character back by one.
  const shiftBack = (ch) => {
    // Preserve non‑printable characters unchanged.
    const code = ch.charCodeAt(0);
    return String.fromCharCode(code - 1);
  };

  // Build the decoded string.
  let result = '';
  for (let i = 0; i < s.length; i++) {
    result += shiftBack(s[i]);
  }
  return result;
};
