/**
 * Returns true if every element in the array `l` is strictly less than `t`.
 *
 * @param {number[]} l - Array of numbers to test.
 * @param {number} t - Threshold value.
 * @returns {boolean} True if all numbers in `l` are below `t`, otherwise false.
 */
const belowThreshold = (l, t) => {
  // If the array is empty, there are no elements that violate the condition.
  if (!Array.isArray(l) || l.length === 0) return true;

  // Use Array.prototype.every to check the condition for all elements.
  return l.every(num => typeof num === 'number' && num < t);
};
