/**
 * Return the n‑th Fibonacci number.
 * Uses an iterative approach for O(n) time and O(1) space.
 *
 * @param {number} n - The index of the Fibonacci number (0‑based).
 * @returns {number} The n‑th Fibonacci number.
 */
const fib = (n) => {
  if (n <= 0) return 0;          // F(0) = 0
  if (n === 1) return 1;         // F(1) = 1

  let prev = 0;                  // F(0)
  let curr = 1;                  // F(1)

  for (let i = 2; i <= n; i++) {
    const next = prev + curr;    // F(i) = F(i-1) + F(i-2)
    prev = curr;
    curr = next;
  }

  return curr;                   // F(n)
};
```

