/**
 * Returns true if the array is monotonically increasing or decreasing.
 * Monotonic means the sequence is either non‑decreasing or non‑increasing.
 *
 * @param {Array<Number>} l - The list of numbers to check.
 * @returns {boolean} True if the list is monotonic, false otherwise.
 */
const monotonic = (l) => {
  if (!Array.isArray(l) || l.length <= 1) return true;

  let increasing = true;
  let decreasing = true;

  for (let i = 1; i < l.length; i++) {
    const prev = l[i - 1];
    const curr = l[i];

    if (curr > prev) decreasing = false;
    if (curr < prev) increasing = false;

    // Early exit if neither direction is possible
    if (!increasing && !decreasing) return false;
  }

  return increasing || decreasing;
};
```

