/**
 * Returns true if the array is monotonically increasing or decreasing.
 * Monotonic means non‑decreasing or non‑increasing (equal elements are allowed).
 *
 * @param {Array<number>} l - The list of numbers to test.
 * @returns {boolean} True if the list is monotonic, false otherwise.
 */
const monotonic = (l) => {
  if (!Array.isArray(l) || l.length <= 1) return true;

  let direction = 0; // 0 = unknown, 1 = increasing, -1 = decreasing

  for (let i = 1; i < l.length; i++) {
    const diff = l[i] - l[i - 1];

    if (diff === 0) continue; // equal elements don't change direction

    if (direction === 0) {
      direction = diff > 0 ? 1 : -1; // establish initial direction
    } else if ((diff > 0 && direction === -1) || (diff < 0 && direction === 1)) {
      return false; // direction changed
    }
  }

  return true;
};
```

