/**
 * Return a sorted array of unique elements that appear in both input lists.
 *
 * @param {Array<number>} l1 - First list of numbers.
 * @param {Array<number>} l2 - Second list of numbers.
 * @returns {Array<number>} Sorted array of unique common elements.
 */
const common = (l1, l2) => {
  // Convert each list to a Set to remove duplicates.
  const set1 = new Set(l1);
  const set2 = new Set(l2);

  // Collect elements that exist in both sets.
  const intersection = [];
  for (const value of set1) {
    if (set2.has(value)) {
      intersection.push(value);
    }
  }

  // Sort numerically in ascending order.
  intersection.sort((a, b) => a - b);

  return intersection;
};
