/**
 * Returns the largest prime factor of a number n (n > 1 and not prime).
 *
 * @param {number} n - The number to factor.
 * @returns {number} The largest prime factor of n.
 */
const largestPrimeFactor = (n) => {
  let maxFactor = 1;

  // Remove factors of 2 first
  while (n % 2 === 0) {
    maxFactor = 2;
    n /= 2;
  }

  // Check odd factors from 3 upwards
  for (let i = 3; i * i <= n; i += 2) {
    while (n % i === 0) {
      maxFactor = i;
      n /= i;
    }
  }

  // If n is now greater than 1, it is a prime factor larger than sqrt(original n)
  if (n > 1) {
    maxFactor = n;
  }

  return maxFactor;
};
```

