const correctBracketing = (brackets) => {
  let balance = 0;          // number of unmatched '(' seen so far

  for (const ch of brackets) {
    if (ch === '(') {
      balance += 1;
    } else if (ch === ')') {
      balance -= 1;
      // If we close more brackets than we opened, it's invalid
      if (balance < 0) return false;
    }
    // (The problem guarantees only '(' and ')' characters, so no else needed)
  }

  // All opening brackets must be matched
  return balance === 0;
};
