/**
 * Compute the derivative of a polynomial represented by its coefficients.
 *
 * @param {number[]} xs - Coefficients of the polynomial, where xs[i] is the coefficient of x^i.
 * @returns {number[]} - Coefficients of the derivative polynomial.
 */
const derivative = (xs) => {
  if (!Array.isArray(xs) || xs.length <= 1) return [];
  const result = new Array(xs.length - 1);
  for (let i = 1; i < xs.length; i++) {
    result[i - 1] = i * xs[i];
  }
  return result;
};
