/**
 * Computes the n-th element of the FibFib sequence.
 *
 * The sequence is defined as:
 *   fibfib(0) = 0
 *   fibfib(1) = 0
 *   fibfib(2) = 1
 *   fibfib(n) = fibfib(n-1) + fibfib(n-2) + fibfib(n-3)   for n >= 3
 *
 * @param {number} n - The index of the element to compute (non‑negative integer).
 * @returns {number} The n-th FibFib number.
 */
const fibfib = (n) => {
  if (n < 0 || !Number.isInteger(n)) {
    throw new Error('n must be a non‑negative integer');
  }

  if (n === 0 || n === 1) return 0;
  if (n === 2) return 1;

  // Use an iterative approach with constant space.
  let a = 0; // fibfib(n-3)
  let b = 0; // fibfib(n-2)
  let c = 1; // fibfib(n-1)

  for (let i = 3; i <= n; i++) {
    const next = a + b + c;
    a = b;
    b = c;
    c = next;
  }

  return c;
};
```

