/**
 * Computes the n‑th FibFib number.
 *
 * The sequence is defined as:
 *   fibfib(0) = 0
 *   fibfib(1) = 0
 *   fibfib(2) = 1
 *   fibfib(n) = fibfib(n-1) + fibfib(n-2) + fibfib(n-3)   (n ≥ 3)
 *
 * The implementation uses an iterative approach with O(n) time
 * and O(1) space.  BigInt is used to avoid overflow for large n.
 *
 * @param {number} n - The index of the FibFib number (must be ≥ 0).
 * @returns {bigint} The n‑th FibFib number.
 */
const fibfib = (n) => {
  if (n < 0) {
    throw new Error('n must be a non‑negative integer');
  }

  // Base cases
  if (n === 0 || n === 1) return 0n;
  if (n === 2) return 1n;

  // Iterative computation
  let a = 0n; // fibfib(n-3)
  let b = 0n; // fibfib(n-2)
  let c = 1n; // fibfib(n-1)

  for (let i = 3; i <= n; i++) {
    const d = a + b + c; // fibfib(i)
    a = b;
    b = c;
    c = d;
  }

  return c;
};
