/**
 * Counts the number of vowels in a word.
 * Vowels are 'a', 'e', 'i', 'o', 'u'.
 * The letter 'y' is considered a vowel only when it appears at the end of the word.
 *
 * @param {string} s - The word to analyze.
 * @returns {number} The count of vowels in the word.
 */
const vowelsCount = (s) => {
  if (typeof s !== 'string') return 0;

  const lower = s.toLowerCase();
  let count = 0;

  for (let i = 0; i < lower.length; i++) {
    const ch = lower[i];
    if ('aeiou'.includes(ch)) {
      count++;
    } else if (ch === 'y' && i === lower.length - 1) {
      count++;
    }
  }

  return count;
};
```

