const circularShift = (x, shift) => {
  const s = String(x);
  const len = s.length;

  // If shift exceeds the number of digits, return the reversed string
  if (shift > len) {
    return s.split('').reverse().join('');
  }

  // Normal circular right shift
  const k = shift % len;          // k == 0 when shift == len
  if (k === 0) return s;          // no change needed

  return s.slice(-k) + s.slice(0, len - k);
};
```

