/**
 * Returns the sum of ASCII codes of all uppercase letters in the given string.
 *
 * @param {string} s - The input string.
 * @returns {number} The sum of ASCII codes of uppercase characters.
 */
const digitSum = (s) => {
  // Helper to determine if a character is an uppercase letter
  const isUppercase = (ch) => ch >= 'A' && ch <= 'Z';

  return s.split('').reduce((sum, ch) => {
    return sum + (isUppercase(ch) ? ch.charCodeAt(0) : 0);
  }, 0);
};
