/**
 * Returns the number of mangoes in a basket.
 *
 * @param {string} s - A string containing the number of apples and oranges,
 *                     e.g. "5 apples and 6 oranges".
 * @param {number} n - The total number of fruits in the basket.
 * @returns {number} The number of mangoes.
 */
const fruitDistribution = (s, n) => {
  // Extract the first two integers from the string.
  const numbers = s.match(/(\d+).*?(\d+)/);
  if (!numbers) return null; // or throw an error if input is guaranteed valid

  const apples = parseInt(numbers[1], 10);
  const oranges = parseInt(numbers[2], 10);

  return n - apples - oranges;
};
```

