/**
 * Circularly shift the decimal digits of an integer to the right.
 *
 * @param {number} x    The integer whose digits are to be shifted.
 * @param {number} shift The number of positions to shift right.
 * @returns {string} The resulting digit sequence as a string.
 *
 * Rules:
 * - If shift > number of digits, return the digits reversed.
 * - Otherwise, perform a right rotation by `shift` positions.
 */
const circularShift = (x, shift) => {
  // Convert the integer to a string of its decimal digits.
  const digits = String(Math.abs(x)); // ignore sign for shifting
  const len = digits.length;

  // If shift exceeds the number of digits, return reversed digits.
  if (shift > len) {
    return digits.split('').reverse().join('');
  }

  // Normal right rotation (shift may be 0).
  const s = shift % len; // safe guard, though shift <= len here
  if (s === 0) return digits;

  const right = digits.slice(-s);
  const left = digits.slice(0, len - s);
  return right + left;
};
```

