/**
 * Returns the greatest integer > 0 that appears in the list at least as many times
 * as its own value. If no such integer exists, returns -1.
 *
 * @param {number[]} lst - Non‑empty array of positive integers.
 * @returns {number} The greatest qualifying integer or -1.
 */
const search = (lst) => {
  // Build frequency map
  const freq = new Map();
  for (const num of lst) {
    freq.set(num, (freq.get(num) || 0) + 1);
  }

  // Find the maximum integer satisfying freq >= value
  let best = -1;
  for (const [num, count] of freq.entries()) {
    if (num > 0 && count >= num && num > best) {
      best = num;
    }
  }

  return best;
};
```

