/**
 * Returns a list sorted in a "strange" order:
 * start with the smallest element, then the largest remaining,
 * then the next smallest, then the next largest, and so on.
 *
 * @param {number[]} lst - Array of integers.
 * @returns {number[]} The array reordered in strange order.
 */
const strangeSortList = (lst) => {
  if (!Array.isArray(lst) || lst.length === 0) return [];

  // Sort ascending to easily pick min and max
  const sorted = [...lst].sort((a, b) => a - b);

  const result = [];
  let left = 0;          // index of next smallest
  let right = sorted.length - 1; // index of next largest

  // Alternate between smallest and largest
  while (left <= right) {
    result.push(sorted[left++]); // smallest
    if (left <= right) {
      result.push(sorted[right--]); // largest
    }
  }

  return result;
};
```

