 * @param {string} brackets - The string containing only '<' and '>' characters.
 * @returns {boolean} - true if the brackets are correctly matched, false otherwise.
 */
const correctBracketing = (brackets) => {
  let depth = 0;
  for (const ch of brackets) {
    if (ch === '<') {
      depth++;
    } else if (ch === '>') {
      if (depth === 0) return false; // closing without matching opening
      depth--;
    } else {
      // ignore any other characters (though the problem guarantees only '<' and '>')
    }
  }
  return depth === 0; // true if all openings were matched
};
