/**
 * Returns the area of a triangle with sides a, b, c rounded to two decimal places.
 * If the sides cannot form a valid triangle, returns -1.
 *
 * @param {number} a - Length of side a
 * @param {number} b - Length of side b
 * @param {number} c - Length of side c
 * @returns {number} Area rounded to 2 decimal places, or -1 if invalid
 */
const triangleArea = (a, b, c) => {
  // Helper to check triangle inequality
  const isValid = (x, y, z) => x + y > z && x + z > y && y + z > x;

  if (!isValid(a, b, c)) return -1;

  const s = (a + b + c) / 2; // semi-perimeter
  const area = Math.sqrt(s * (s - a) * (s - b) * (s - c));

  // Round to two decimal places and return as a number
  return parseFloat(area.toFixed(2));
};
```

