 * Checks if an array is a palindrome (balanced).
 * @param {Array<number>} arr
 * @returns {boolean}
 */
const isPalindrome = (arr) => {
  const len = arr.length;
  for (let i = 0; i < Math.floor(len / 2); i++) {
    if (arr[i] !== arr[len - 1 - i]) return false;
  }
  return true;
};

/**
 * Determines whether the object will fly.
 * @param {Array<number>} q - The list of weights.
 * @param {number} w - The maximum possible weight.
 * @returns {boolean} True if q is balanced and its sum is <= w, otherwise false.
 */
const willItFly = (q, w) => {
  if (!Array.isArray(q)) return false; // defensive check
  const sum = q.reduce((acc, val) => acc + val, 0);
  return isPalindrome(q) && sum <= w;
};
