const isPrime = (n) => {
  if (n < 2) return false;
  for (let i = 2; i * i <= n; i++) {
    if (n % i === 0) return false;
  }
  return true;
};

// Main function: true if the number is a product of exactly three prime numbers
const isMultiplyPrime = (a) => {
  if (a < 8) return false; // 2*2*2 is the smallest product of 3 primes

  for (let p = 2; p <= a; p++) {
    if (!isPrime(p)) continue;
    for (let q = 2; q <= a; q++) {
      if (!isPrime(q)) continue;
      const pq = p * q;
      if (pq > a) continue;
      const r = a / pq;
      if (Number.isInteger(r) && isPrime(r)) return true;
    }
  }
  return false;
};
