const isMultiplyPrime = (a) => {
  // Only positive integers less than 100 are considered
  if (!Number.isInteger(a) || a <= 1) return false;

  let count = 0;
  let n = a;

  // Factorise n and count prime factors (with multiplicity)
  for (let i = 2; i * i <= n; i++) {
    while (n % i === 0) {
      count++;
      n /= i;
      if (count > 3) return false; // early exit if more than 3 factors
    }
  }

  // If n > 1, it is a prime factor remaining
  if (n > 1) count++;

  return count === 3;
};
