 * @param {number} a - The integer to test.
 * @returns {boolean}
 */
const iscube = (a) => {
  // Math.cbrt works for negative numbers as well.
  const root = Math.cbrt(a);
  // Round to nearest integer to avoid floating‑point inaccuracies.
  const rounded = Math.round(root);
  // Check if the rounded integer cubed equals the original number.
  return rounded * rounded * rounded === a;
};
