const hexKey = (num) => {
  if (!num) return 0; // handle empty string

  const primeDigits = new Set(['2', '3', '5', '7', 'B', 'D']);
  let count = 0;

  for (const ch of num) {
    if (primeDigits.has(ch)) count++;
  }

  return count;
};
