const isSimplePower = (x, n) => {
  // Trivial cases
  if (x === 1) return true;                 // 1 = n^0 for any n
  if (n === 1) return x === 1;              // only 1^k = 1
  if (n === -1) return x === 1 || x === -1; // (-1)^k alternates 1 and -1
  if (n === 0) return x === 0;              // 0^k = 0 for k > 0
  if (x === 0) return false;                // no positive power of non‑zero n equals 0

  let current = x;
  while (current % n === 0) {
    current /= n;
    if (current === 1) return true;
  }
  return false;
};
