/**
 * Convert a decimal integer to a binary string wrapped with "db" markers.
 *
 * @param {number} decimal - The decimal integer to convert.
 * @returns {string} The binary representation surrounded by "db".
 * @throws {TypeError} If the input is not a finite integer.
 */
const decimalToBinary = (decimal) => {
  if (typeof decimal !== 'number' || !Number.isFinite(decimal)) {
    throw new TypeError('Input must be a finite number');
  }
  if (!Number.isInteger(decimal)) {
    throw new TypeError('Input must be an integer');
  }

  const binary = decimal.toString(2); // Convert to binary string
  return `db${binary}db`;
};
```

