/**
 * Checks whether a string is "happy".
 * A string is happy if:
 *   1. Its length is at least 3.
 *   2. Every group of three consecutive characters contains three distinct characters.
 *
 * @param {string} s - The string to test.
 * @returns {boolean} - True if the string is happy, false otherwise.
 */
const isHappy = (s) => {
  if (s.length < 3) return false;

  for (let i = 0; i <= s.length - 3; i++) {
    const a = s[i];
    const b = s[i + 1];
    const c = s[i + 2];
    if (a === b || a === c || b === c) return false;
  }

  return true;
};
```

