/**
 * Returns true if `x` is a simple power of `n` (i.e. there exists an integer k such that n**k === x).
 * Handles positive, negative, and zero bases and exponents.
 *
 * @param {number} x - The target value.
 * @param {number} n - The base.
 * @returns {boolean}
 */
const isSimplePower = (x, n) => {
  // Basic sanity checks
  if (!Number.isInteger(x) || !Number.isInteger(n)) return false;

  // 0^k = 0 for any positive k
  if (x === 0) return n === 0;

  // 1 is n^0 for any n ≠ 0
  if (x === 1) return n !== 0;

  // Handle special bases
  if (n === 0) return false;          // 0^k ≠ 1, and 0^k ≠ any non‑zero x
  if (n === 1) return x === 1;        // 1^k = 1
  if (n === -1) return x === 1 || x === -1; // (-1)^k alternates between 1 and -1

  // For all other bases, iterate until we reach or exceed the target
  let power = 1;
  while (true) {
    if (power === x) return true;

    // If the absolute value of power already exceeds that of x, we can stop
    if (Math.abs(power) > Math.abs(x)) return false;

    // Multiply by the base
    power *= n;

    // Guard against overflow / Infinity
    if (!Number.isFinite(power)) return false;
  }
};
```

