// Returns true if the length of the given string is a prime number
const primeLength = (string) => {
  const len = string.length;
  if (len < 2) return false;          // 0 and 1 are not prime

  // Check divisibility up to the square root of len
  const sqrt = Math.floor(Math.sqrt(len));
  for (let i = 2; i <= sqrt; i++) {
    if (len % i === 0) return false;  // divisible by i → not prime
  }
  return true;                        // no divisors found → prime
};
