/**
 * Count the n‑digit positive integers that start or end with 1.
 *
 * @param {number} n - The number of digits (n ≥ 1).
 * @returns {bigint} The count of such numbers.
 */
const startsOneEnds = (n) => {
  if (n < 1) throw new Error('n must be a positive integer');

  // For a single‑digit number, only the number 1 satisfies the condition.
  if (n === 1) return 1n;

  const pow10 = (exp) => 10n ** BigInt(exp);

  const startCount = pow10(n - 1);          // first digit fixed to 1
  const endCount   = 9n * pow10(n - 2);     // last digit fixed to 1, first digit 1‑9
  const bothCount  = pow10(n - 2);          // first and last digits fixed to 1

  return startCount + endCount - bothCount;
};
