/**
 * Returns the binary representation of the sum of the decimal digits of N.
 *
 * @param {number} N - A non‑negative integer (0 ≤ N ≤ 10000).
 * @returns {string} Binary string of the digit sum.
 */
const solve = (N) => {
  // Ensure N is a non‑negative integer
  const num = Math.trunc(Math.abs(N));

  // Sum the decimal digits
  const digitSum = num
    .toString()
    .split('')
    .reduce((acc, ch) => acc + Number(ch), 0);

  // Convert the sum to binary string
  return digitSum.toString(2);
};
