/**
 * Returns the sum of the decimal digits of N, expressed as a binary string.
 *
 * @param {number} N - A non‑negative integer (0 ≤ N ≤ 10000).
 * @returns {string} Binary representation of the digit sum.
 */
const solve = (N) => {
  // Compute the sum of decimal digits
  let sum = 0;
  let temp = N;
  while (temp > 0) {
    sum += temp % 10;
    temp = Math.floor(temp / 10);
  }

  // Convert the sum to binary string
  return sum.toString(2);
};
