const getRow = (lst, x) => {
  const result = [];

  for (let rowIndex = 0; rowIndex < lst.length; rowIndex++) {
    const row = lst[rowIndex];
    if (!Array.isArray(row)) continue; // skip non‑array rows

    const cols = [];
    for (let colIndex = 0; colIndex < row.length; colIndex++) {
      if (row[colIndex] === x) {
        cols.push(colIndex);
      }
    }

    if (cols.length) {
      // sort columns descending
      cols.sort((a, b) => b - a);
      for (const col of cols) {
        result.push([rowIndex, col]);
      }
    }
  }

  return result;
};
