/**
 * Returns a sorted copy of the input array.
 * If the sum of the first and last elements is odd, the array is sorted in ascending order.
 * If the sum is even, the array is sorted in descending order.
 *
 * @param {number[]} array - An array of non‑negative integers.
 * @returns {number[]} A new array sorted according to the rule above.
 */
const sortArray = (array) => {
  // Create a shallow copy so the original array is not mutated
  const copy = [...array];

  // Empty array or single element – no sorting needed
  if (copy.length <= 1) return copy;

  const sum = copy[0] + copy[copy.length - 1];
  const ascending = sum % 2 !== 0; // odd => ascending, even => descending

  return copy.sort((a, b) => ascending ? a - b : b - a);
};
