/**
 * Shift a single lowercase letter forward by 4 positions in the alphabet,
 * wrapping around from 'z' to 'a'. Non‑alphabetic characters are returned unchanged.
 * @param {string} ch - A single character.
 * @returns {string} The shifted character.
 */
const shiftByFour = (ch) => {
  const code = ch.charCodeAt(0);
  if (code >= 97 && code <= 122) { // 'a' to 'z'
    const shifted = ((code - 97 + 4) % 26) + 97;
    return String.fromCharCode(shifted);
  }
  return ch;
};

/**
 * Encrypt a string by rotating each lowercase alphabetic character
 * forward by four positions (2 * 2). Non‑alphabetic characters are left unchanged.
 * @param {string} s - The input string to encrypt.
 * @returns {string} The encrypted string.
 */
const encrypt = (s) => {
  return [...s].map(shiftByFour).join('');
};
