/**
 * Returns the second smallest distinct element in the list.
 * If the list has fewer than two distinct values, returns null.
 *
 * @param {number[]} lst - Array of integers.
 * @returns {number|null} The second smallest distinct element or null.
 */
const nextSmallest = (lst) => {
  if (!Array.isArray(lst) || lst.length === 0) return null;

  let smallest = Infinity;
  let second = Infinity;

  for (const num of lst) {
    if (num < smallest) {
      second = smallest;
      smallest = num;
    } else if (num > smallest && num < second) {
      second = num;
    }
  }

  return second === Infinity ? null : second;
};
```

