/**
 * Encrypts a string by shifting each alphabetic character forward by 4 positions
 * (Caesar cipher with a shift of 4). Non‑alphabetic characters are left unchanged.
 *
 * @param {string} s - The input string to encrypt.
 * @returns {string} The encrypted string.
 */
const encrypt = (s) => {
  const shift = 4;
  const aCode = 'a'.charCodeAt(0);
  const ACode = 'A'.charCodeAt(0);

  return s.split('').map((ch) => {
    const code = ch.charCodeAt(0);

    // Lowercase letters
    if (code >= aCode && code < aCode + 26) {
      return String.fromCharCode(((code - aCode + shift) % 26) + aCode);
    }

    // Uppercase letters
    if (code >= ACode && code < ACode + 26) {
      return String.fromCharCode(((code - ACode + shift) % 26) + ACode);
    }

    // Non‑alphabetic characters remain unchanged
    return ch;
  }).join('');
};
```

