/**
 * Returns the second smallest distinct element in an array of integers.
 * If the array has fewer than two distinct values, returns null.
 *
 * @param {number[]} lst - The input array of integers.
 * @returns {number|null} The second smallest distinct element or null.
 */
const nextSmallest = (lst) => {
  if (!Array.isArray(lst) || lst.length === 0) return null;

  let min1 = Infinity;
  let min2 = Infinity;

  for (const val of lst) {
    if (val < min1) {
      min2 = min1;
      min1 = val;
    } else if (val > min1 && val < min2) {
      min2 = val;
    }
  }

  return min2 === Infinity ? null : min2;
};
