 * Sentences are delimited by '.', '?' or '!'.
 *
 * @param {string} S - The input string containing words and punctuation.
 * @returns {number} The number of boredoms (sentences starting with "I").
 */
const isBored = (S) => {
  // Split the string on sentence delimiters.
  const parts = S.split(/[.!?]/);

  // Determine if the string ends with a delimiter.
  const endsWithDelimiter = /[.!?]$/.test(S);

  let count = 0;

  for (let i = 0; i < parts.length; i++) {
    // Skip the last part if the string does not end with a delimiter
    // (it would not be a complete sentence).
    if (!endsWithDelimiter && i === parts.length - 1) continue;

    const sentence = parts[i].trim();

    // Skip empty sentences (e.g., consecutive delimiters).
    if (!sentence) continue;

    // Check if the sentence starts with the word "I".
    // The word must be followed by a space or be the only word.
    if (/^I(\s|$)/.test(sentence)) {
      count++;
    }
  }

  return count;
};
