/**
 * Encode a message by swapping case of all letters and replacing vowels
 * with the letter that appears two places ahead in the alphabet.
 *
 * @param {string} message - The input string containing only letters.
 * @returns {string} The encoded string.
 */
const encode = (message) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  let result = '';

  for (const ch of message) {
    // Swap case
    const swapped = ch === ch.toUpperCase() ? ch.toLowerCase() : ch.toUpperCase();

    // If the original character is a vowel, replace it
    if (vowels.has(ch.toLowerCase())) {
      const isUpper = swapped === swapped.toUpperCase();
      const base = isUpper ? 65 : 97;          // 'A' or 'a'
      const offset = swapped.charCodeAt(0) - base;
      const newOffset = (offset + 2) % 26;     // 2 places ahead
      const newCode = base + newOffset;
      result += String.fromCharCode(newCode);
    } else {
      result += swapped;
    }
  }

  return result;
};
```

