/**
 * Returns the sum of the digits of the largest prime number in the list.
 * @param {number[]} lst - Array of integers.
 * @returns {number} Sum of digits of the largest prime found.
 */
const skjkasdkd = (lst) => {
  // Helper to check primality
  const isPrime = (n) => {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 === 0 || n % 3 === 0) return false;
    for (let i = 5; i * i <= n; i += 6) {
      if (n % i === 0 || n % (i + 2) === 0) return false;
    }
    return true;
  };

  let maxPrime = null;

  for (const num of lst) {
    if (Number.isInteger(num) && num > 1 && isPrime(num)) {
      if (maxPrime === null || num > maxPrime) {
        maxPrime = num;
      }
    }
  }

  if (maxPrime === null) return 0; // No prime found

  // Sum digits of maxPrime
  let sum = 0;
  for (const ch of String(maxPrime)) {
    sum += ch.charCodeAt(0) - 48; // '0'.charCodeAt(0) === 48
  }
  return sum;
};
