/**
 * Checks whether all keys of a dictionary are either all lower‑case
 * or all upper‑case strings. Returns false for an empty dictionary
 * or if any key is not a string.
 *
 * @param {Object} dict - The dictionary to check.
 * @returns {boolean} - true if all keys are uniformly lower or upper case, otherwise false.
 */
const checkDictCase = (dict) => {
  // Get all keys of the object
  const keys = Object.keys(dict);

  // Empty dictionary → false
  if (keys.length === 0) return false;

  // Flags to determine if all keys are lower or upper case
  let allLower = true;
  let allUpper = true;

  for (const key of keys) {
    // Key must be a string
    if (typeof key !== 'string') return false;

    // Check case
    if (key !== key.toLowerCase()) allLower = false;
    if (key !== key.toUpperCase()) allUpper = false;

    // Early exit if neither flag can be true
    if (!allLower && !allUpper) return false;
  }

  // Return true if either all lower or all upper
  return allLower || allUpper;
};
