/**
 * Checks whether all keys of a dictionary are either all lower‑case
 * or all upper‑case strings. Returns false for an empty dictionary
 * or if any key is not a string or is mixed case.
 *
 * @param {Object} dict - The dictionary to check.
 * @returns {boolean} - true if all keys are uniformly lower or upper case, false otherwise.
 */
const checkDictCase = (dict) => {
  // Ensure the input is an object
  if (typeof dict !== 'object' || dict === null) return false;

  const keys = Object.keys(dict);
  if (keys.length === 0) return false; // empty dictionary

  let caseType = null; // 'lower' or 'upper'

  for (const key of keys) {
    if (typeof key !== 'string') return false; // non‑string key

    const isLower = key === key.toLowerCase();
    const isUpper = key === key.toUpperCase();

    if (!isLower && !isUpper) return false; // mixed case or non‑alphabetic

    const currentCase = isLower ? 'lower' : 'upper';

    if (caseType === null) {
      caseType = currentCase;
    } else if (caseType !== currentCase) {
      return false; // mixed case detected
    }
  }

  return true;
};
