/**
 * Creates a pile of stones with `n` levels.
 * The first level contains `n` stones.
 * Each subsequent level contains the next odd number if the current level
 * has an odd number of stones, or the next even number if the current level
 * has an even number of stones.  In either case the value increases by 2.
 *
 * @param {number} n - The number of levels (must be a positive integer).
 * @returns {number[]} An array where the element at index i represents the
 *                     number of stones in level i+1.
 */
const makeAPile = (n) => {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('n must be a positive integer');
  }

  const pile = [];
  let current = n;

  for (let i = 0; i < n; i++) {
    pile.push(current);
    current += 2; // next odd or even number
  }

  return pile;
};
```

