/**
 * Returns the integer closest to the numeric value represented by the input string.
 * If the value is exactly halfway between two integers, the result is the integer
 * that is farther from zero (i.e., rounds away from zero).
 *
 * @param {string} value - A string representation of a number.
 * @returns {number} The closest integer, or NaN if the input cannot be parsed.
 */
const closestInteger = (value) => {
  const num = Number(value);
  if (isNaN(num)) return NaN;

  const floor = Math.floor(num);
  const ceil  = Math.ceil(num);

  // If the number is already an integer, return it.
  if (floor === ceil) return floor;

  const diffFloor = Math.abs(num - floor);
  const diffCeil  = Math.abs(ceil - num);

  if (diffFloor < diffCeil) return floor;
  if (diffCeil < diffFloor) return ceil;

  // Exactly halfway: round away from zero.
  if (num > 0) return ceil;
  if (num < 0) return floor;
  return 0; // num === 0
};
```

