/**
 * Returns the largest even integer within the inclusive range [x, y].
 * If no such integer exists, returns -1.
 *
 * @param {number} x - The lower bound of the range (positive number).
 * @param {number} y - The upper bound of the range (positive number).
 * @returns {number} The largest even integer in the range, or -1 if none.
 */
const chooseNum = (x, y) => {
  // Ensure the bounds are numbers
  if (typeof x !== 'number' || typeof y !== 'number') return -1;

  // If the range is invalid (x > y), no numbers exist
  if (x > y) return -1;

  // Convert bounds to integer limits
  const start = Math.ceil(x);   // first integer >= x
  const end   = Math.floor(y);  // last integer <= y

  // If no integers in the range
  if (start > end) return -1;

  // Find the largest even integer <= end
  const candidate = (end % 2 === 0) ? end : end - 1;

  // Check if the candidate is within the range
  return candidate >= start ? candidate : -1;
};
```

