/**
 * Computes the average of all integers from n to m (inclusive),
 * rounds it to the nearest integer, and returns that value in binary
 * prefixed with "0b". If n is greater than m, returns -1.
 *
 * @param {number} n - The starting integer (positive).
 * @param {number} m - The ending integer (positive).
 * @returns {string|number} The binary representation of the rounded average,
 *                          or -1 if n > m.
 */
const roundedAvg = (n, m) => {
  if (n > m) return -1;

  // The average of consecutive integers from n to m is simply (n + m) / 2.
  const avg = (n + m) / 2;

  // Round to the nearest integer.
  const rounded = Math.round(avg);

  // Convert to binary string with "0b" prefix.
  return `0b${rounded.toString(2)}`;
};
```

