/**
 * Returns a sorted array of all numbers from the input that contain only odd digits.
 *
 * @param {number[]} arr - Array of positive integers.
 * @returns {number[]} Sorted array of numbers with no even digits.
 */
const uniqueDigits = (arr) => {
  // Helper: check if a number contains only odd digits
  const hasOnlyOddDigits = (n) => {
    while (n > 0) {
      const digit = n % 10;
      if (digit % 2 === 0) return false; // even digit found
      n = Math.floor(n / 10);
    }
    return true;
  };

  return arr
    .filter(hasOnlyOddDigits)
    .sort((a, b) => a - b);
};
```

