/**
 * Returns a sorted array of all numbers from the input that contain
 * no even digits (i.e., every digit is odd).
 *
 * @param {number[]} x - Array of positive integers.
 * @returns {number[]} Sorted array of numbers with only odd digits.
 */
const uniqueDigits = (x) => {
  // Helper: true if the number has at least one even digit
  const hasEvenDigit = (n) => {
    while (n > 0) {
      const d = n % 10;
      if (d % 2 === 0) return true; // even digit found
      n = Math.floor(n / 10);
    }
    return false; // all digits are odd
  };

  // Filter numbers that have no even digits
  const filtered = x.filter((num) => !hasEvenDigit(num));

  // Sort in ascending order
  filtered.sort((a, b) => a - b);

  return filtered;
};
```

