// Convert a digit to its English name
const digitNames = [
  "One", "Two", "Three", "Four", "Five",
  "Six", "Seven", "Eight", "Nine"
];

/**
 * Sorts the integers 1‑9 in ascending order, reverses the result,
 * and replaces each digit with its English name.
 *
 * @param {number[]} arr - The input array of integers.
 * @returns {string[]} An array of digit names in the required order.
 */
const byLength = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) return [];

  // Sort numerically ascending
  const sorted = [...arr].sort((a, b) => a - b);

  // Reverse the sorted array
  const reversed = sorted.reverse();

  // Keep only digits 1‑9 and map to names
  return reversed
    .filter(n => Number.isInteger(n) && n >= 1 && n <= 9)
    .map(n => digitNames[n - 1]);
};
