/**
 * Check if a positive integer is a palindrome.
 * @param {number} num
 * @returns {boolean}
 */
const isPalindrome = (num) => {
  const s = String(num);
  const rev = s.split('').reverse().join('');
  return s === rev;
};

/**
 * Count even and odd integer palindromes in the range [1, n].
 * @param {number} n - Positive integer (1 ≤ n ≤ 10³)
 * @returns {[number, number]} Tuple: [evenCount, oddCount]
 */
const evenOddPalindrome = (n) => {
  let evenCount = 0;
  let oddCount = 0;

  for (let i = 1; i <= n; i++) {
    if (isPalindrome(i)) {
      if (i % 2 === 0) {
        evenCount++;
      } else {
        oddCount++;
      }
    }
  }

  return [evenCount, oddCount];
};
