/**
 * Count how many numbers in the array have a sum of digits greater than 0.
 * For negative numbers, the first digit is considered negative.
 *
 * @param {number[]} arr - Array of integers.
 * @returns {number} The count of numbers with digit sum > 0.
 */
const countNums = (arr) => {
  let count = 0;

  for (const num of arr) {
    const str = Math.abs(num).toString(); // digits without sign
    let sum = 0;

    for (let i = 0; i < str.length; i++) {
      const digit = Number(str[i]);

      // If the original number was negative and this is the first digit,
      // subtract it instead of adding.
      if (num < 0 && i === 0) {
        sum -= digit;
      } else {
        sum += digit;
      }
    }

    if (sum > 0) {
      count++;
    }
  }

  return count;
};
```

