/**
 * Returns the sum of the signed digits of a number.
 * For negative numbers the first digit is treated as negative.
 *
 * @param {number} n
 * @returns {number}
 */
const signedDigitSum = (n) => {
  const str = Math.abs(n).toString();          // absolute value string
  const firstDigit = parseInt(str[0], 10);     // first digit
  let sumAbs = 0;

  for (let i = 0; i < str.length; i++) {
    sumAbs += parseInt(str[i], 10);
  }

  // If the original number was negative, subtract twice the first digit
  return n < 0 ? sumAbs - 2 * firstDigit : sumAbs;
};

/**
 * Counts how many numbers in the array have a signed digit sum > 0.
 *
 * @param {number[]} arr
 * @returns {number}
 */
const countNums = (arr) => {
  let count = 0;
  for (const num of arr) {
    if (signedDigitSum(num) > 0) {
      count++;
    }
  }
  return count;
};
```

