/**
 * Returns the sum of the signed digits of a number.
 * For negative numbers the first digit is treated as negative.
 *
 * @param {number} n
 * @returns {number}
 */
const sumSignedDigits = (n) => {
  const isNegative = n < 0;
  const digits = Math.abs(n).toString().split('');
  let sum = 0;

  digits.forEach((ch, idx) => {
    const d = parseInt(ch, 10);
    if (idx === 0 && isNegative) {
      sum -= d;          // first digit is negative
    } else {
      sum += d;          // subsequent digits are positive
    }
  });

  return sum;
};

