 * Determines whether the given array can be sorted in non‑decreasing order
 * by performing any number of right cyclic shift operations.
 *
 * @param {number[]} arr - Array of unique integers.
 * @returns {boolean} - true if a sorted array can be obtained, otherwise false.
 */
const moveOneBall = (arr) => {
  const n = arr.length;
  if (n <= 1) return true; // empty or single element is already sorted

  let dropCount = 0; // number of places where arr[i] > arr[i+1] (cyclically)
  for (let i = 0; i < n; i++) {
    const next = (i + 1) % n;
    if (arr[i] > arr[next]) dropCount++;
  }

  // If no drops, array is already sorted.
  if (dropCount === 0) return true;

  // For a rotation of a sorted array there must be exactly one drop
  // and the last element must be <= the first element.
  return dropCount === 1 && arr[n - 1] <= arr[0];
};
