/**
 * Determines whether an array can be sorted in non‑decreasing order
 * by performing any number of right shift operations.
 *
 * @param {number[]} arr - The input array of unique integers.
 * @returns {boolean} - True if the array can be sorted by right shifts, otherwise false.
 */
const moveOneBall = (arr) => {
  const n = arr.length;
  if (n <= 1) return true; // empty or single element is already sorted

  let breakCount = 0;

  // Count inversions where arr[i] > arr[i+1] for i = 0 .. n-2
  for (let i = 0; i < n - 1; i++) {
    if (arr[i] > arr[i + 1]) breakCount++;
  }

  // Check the wrap‑around inversion between last and first element
  if (arr[n - 1] > arr[0]) breakCount++;

  // The array is a rotation of a sorted array if there are
  // either 0 inversions (already sorted) or exactly 1 inversion
  // (the rotation point) and the last element is <= the first.
  return breakCount === 0 || (breakCount === 1 && arr[n - 1] <= arr[0]);
};
