/**
 * Returns an object containing the letter(s) that appear most frequently
 * in a space‑separated string of lowercase letters, along with their count.
 *
 * @param {string} test - Space separated lowercase letters.
 * @returns {Object} An object mapping the most frequent letter(s) to their count.
 */
const histogram = (test) => {
  // Return empty object for null/undefined or empty string
  if (!test || test.trim() === '') return {};

  // Split the string into individual letters, ignoring any extra whitespace
  const letters = test.trim().split(/\s+/).filter(Boolean);

  // Count occurrences of each letter
  const counts = {};
  for (const letter of letters) {
    counts[letter] = (counts[letter] || 0) + 1;
  }

  // Find the maximum count
  let maxCount = 0;
  for (const key in counts) {
    if (counts[key] > maxCount) maxCount = counts[key];
  }

  // Build the result object with all letters that have the maximum count
  const result = {};
  for (const key in counts) {
    if (counts[key] === maxCount) result[key] = maxCount;
  }

  return result;
};
