  const words = test.trim().split(/\s+/).filter(Boolean);

  if (words.length === 0) return {};

  // Count occurrences
  const freq = {};
  for (const ch of words) {
    freq[ch] = (freq[ch] || 0) + 1;
  }

  // Find maximum count
  const maxCount = Math.max(...Object.values(freq));

  // Build result with all letters that have the maximum count
  const result = {};
  for (const [ch, count] of Object.entries(freq)) {
    if (count === maxCount) result[ch] = count;
  }

  return result;
};
