/**
 * Remove all characters from `s` that appear in `c` and check if the
 * resulting string is a palindrome.
 *
 * @param {string} s - The original string.
 * @param {string} c - The string containing characters to delete.
 * @returns {[string, boolean]} A tuple where the first element is the
 *          resulting string and the second element is true if it is a
 *          palindrome, otherwise false.
 */
const reverseDelete = (s, c) => {
  // Build a set of characters to delete for O(1) lookup
  const deleteSet = new Set(c.split(''));

  // Filter out characters that are in the delete set
  const filtered = [...s].filter(ch => !deleteSet.has(ch)).join('');

  // Check if the filtered string is a palindrome
  const isPalindrome = filtered === [...filtered].reverse().join('');

  return [filtered, isPalindrome];
};
