/**
 * Returns the minimum sum of any non‑empty sub‑array of the given array.
 *
 * @param {number[]} nums - Array of integers.
 * @returns {number} The minimum sub‑array sum.
 */
const minSubArraySum = (nums) => {
  if (!Array.isArray(nums) || nums.length === 0) {
    throw new Error('Input must be a non‑empty array of numbers.');
  }

  let currentMin = nums[0];
  let globalMin = nums[0];

  for (let i = 1; i < nums.length; i++) {
    const val = nums[i];
    // Minimum sub‑array ending at index i
    currentMin = Math.min(val, currentMin + val);
    // Update global minimum
    globalMin = Math.min(globalMin, currentMin);
  }

  return globalMin;
};
