/**
 * Calculates the minimum number of times a bucket must be lowered
 * to empty all wells in the grid.
 *
 * @param {number[][]} grid - 2D array where each row represents a well
 *                            and each 1 indicates one unit of water.
 * @param {number} capacity - Capacity of each bucket (units of water it can hold).
 * @returns {number} The minimum number of bucket lowers required.
 */
const maxFill = (grid, capacity) => {
  if (!Array.isArray(grid) || grid.length === 0 || capacity <= 0) return 0;

  let totalLowers = 0;

  for (const row of grid) {
    // Count the number of 1's in the current row (units of water)
    const units = row.reduce((sum, val) => sum + (val === 1 ? 1 : 0), 0);

    // If there are units, compute how many bucket lowers are needed
    if (units > 0) {
      totalLowers += Math.ceil(units / capacity);
    }
  }

  return totalLowers;
};
