/**
 * Count the number of '1' bits in the binary representation of a number.
 * The function works for both positive and negative integers by using the
 * absolute value of the number.
 *
 * @param {number} n - The number to count bits for.
 * @returns {number} The count of '1' bits.
 */
const countOnes = (n) => {
  // Use absolute value to avoid issues with negative two's‑complement
  // representation. For non‑negative numbers this is identical to n.
  const binary = Math.abs(n).toString(2);
  // Count '1's in the binary string
  return binary.split('0').join('').length;
};

/**
 * Sort an array of integers according to the number of ones in their binary
 * representation (ascending). If two numbers have the same number of ones,
 * they are sorted by their decimal value (ascending).
 *
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} A new array sorted as described.
 */
const sortArray = (arr) => {
  // Create a shallow copy to avoid mutating the original array
  return [...arr].sort((a, b) => {
    const onesA = countOnes(a);
    const onesB = countOnes(b);

    if (onesA !== onesB) {
      return onesA - onesB; // ascending by number of ones
    }
    return a - b; // ascending by decimal value
  });
};
