/**
 * Count the number of 1‑bits in the binary representation of a non‑negative integer.
 * @param {number} n - A non‑negative integer.
 * @returns {number} The number of 1‑bits.
 */
const countOnes = (n) => {
  // Convert to binary string, remove any leading '-' (for safety), and count '1's.
  return n.toString(2).replace('-', '').split('').filter(ch => ch === '1').length;
};

/**
 * Sort an array of integers by the number of 1‑bits in their binary representation
 * (ascending). If two numbers have the same bit count, they are sorted by their
 * decimal value (ascending). Negative numbers are sorted by their numeric value.
 *
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} A new array sorted according to the rules above.
 */
const sortArray = (arr) => {
  // Work on a copy to avoid mutating the original array.
  return arr.slice().sort((a, b) => {
    // If either number is negative, fall back to normal numeric comparison.
    if (a < 0 || b < 0) {
      return a - b;
    }

    const onesA = countOnes(a);
    const onesB = countOnes(b);

    if (onesA !== onesB) {
      return onesA - onesB; // fewer 1‑bits come first
    }
    return a - b; // tie‑break by decimal value
  });
};
