/**
 * Count the number of 1 bits in the 32‑bit binary representation of a number.
 * For negative numbers the two's‑complement representation is used.
 *
 * @param {number} n
 * @returns {number}
 */
const countOnes = (n) => {
  let count = 0;
  let num = n >>> 0;          // convert to unsigned 32‑bit integer
  while (num) {
    count += num & 1;
    num >>>= 1;
  }
  return count;
};

/**
 * Sort an array of integers by the number of 1s in their binary representation
 * (ascending). If two numbers have the same count, they are sorted by their
 * decimal value (ascending).
 *
 * @param {number[]} arr
 * @returns {number[]}
 */
const sortArray = (arr) => {
  return arr.slice().sort((a, b) => {
    const ca = countOnes(a);
    const cb = countOnes(b);
    if (ca !== cb) return ca - cb;
    return a - b;
  });
};
