/**
 * Returns an array of words from `s` that contain exactly `n` consonants.
 * Words are separated by spaces. The order of words in the result
 * matches their order in the original string.
 *
 * @param {string} s - The input string containing only letters and spaces.
 * @param {number} n - The exact number of consonants a word must contain.
 * @returns {string[]} An array of matching words, or an empty array if none.
 */
const selectWords = (s, n) => {
  if (!s || s.trim() === '') return [];

  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const words = s.trim().split(/\s+/);
  const result = [];

  for (const word of words) {
    let consonantCount = 0;
    for (const ch of word) {
      const lower = ch.toLowerCase();
      if (/[a-z]/.test(lower) && !vowels.has(lower)) {
        consonantCount++;
      }
    }
    if (consonantCount === n) {
      result.push(word);
    }
  }

  return result;
};
