 * @param {number} n - The integer to count bits for (assumed non‑negative).
 * @returns {number} The number of 1‑bits.
 */
const countOnes = (n) => {
  let count = 0;
  // Use unsigned right shift to avoid sign extension.
  let num = n >>> 0;
  while (num) {
    count += num & 1;
    num >>>= 1;
  }
  return count;
};

/**
 * Sorts an array of integers by the number of 1‑bits in their binary representation.
 * For equal bit counts, the numbers are sorted by their decimal value.
 *
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} A new array sorted according to the rules.
 */
const sortArray = (arr) => {
  // Create a shallow copy to avoid mutating the original array.
  return arr.slice().sort((a, b) => {
    const onesA = countOnes(a);
    const onesB = countOnes(b);
    if (onesA !== onesB) return onesA - onesB;
    return a - b;
  });
};
