/**
 * Counts the number of consonants in a word.
 * Vowels are a, e, i, o, u (case‑insensitive).
 * @param {string} word
 * @returns {number}
 */
const countConsonants = (word) => {
  let count = 0;
  for (const ch of word) {
    const lower = ch.toLowerCase();
    if (/[a-z]/.test(lower) && !/[aeiou]/.test(lower)) {
      count++;
    }
  }
  return count;
};

/**
 * Returns an array of words from the input string that contain exactly n consonants.
 * @param {string} s - Input string containing only letters and spaces.
 * @param {number} n - Target number of consonants.
 * @returns {string[]} Array of matching words in the order they appear.
 */
const selectWords = (s, n) => {
  if (!s) return [];

  const words = s.split(' ').filter(Boolean);
  const result = [];

  for (const word of words) {
    if (countConsonants(word) === n) {
      result.push(word);
    }
  }

  return result;
};
