/**
 * Analyze a parenthesis string.
 * @param {string} s
 * @returns {{net: number, minPref: number}}
 */
const analyze = (s) => {
  let balance = 0;
  let minPref = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      balance += 1;
    } else { // ')'
      balance -= 1;
    }
    if (balance < minPref) minPref = balance;
  }
  return { net: balance, minPref };
};

/**
 * Determine if two strings of parentheses can be concatenated in some order
 * to form a balanced string.
 * @param {string[]} lst - Array of two strings containing only '(' and ')'.
 * @returns {string} 'Yes' if a balanced concatenation exists, otherwise 'No'.
 */
const matchParens = (lst) => {
  if (!Array.isArray(lst) || lst.length !== 2) return 'No';

  const [s1, s2] = lst;
  const a1 = analyze(s1);
  const a2 = analyze(s2);

  // Helper to test a specific order
  const canOrder = (first, second) => {
    // First string must be internally balanced enough
    if (first.minPref < 0) return false;
    // After first string, second string's prefixes must not go negative
    if (second.minPref + first.net < 0) return false;
    // Total net must be zero
    return first.net + second.net === 0;
  };

  if (canOrder(a1, a2) || canOrder(a2, a1)) {
    return 'Yes';
  }
  return 'No';
};
