/**
 * Returns the closest vowel (from the right) that is surrounded by consonants.
 * Vowels are aeiouAEIOU. A vowel at the start or end of the word is ignored.
 *
 * @param {string} word - The word to search.
 * @returns {string} The vowel found or an empty string if none.
 */
const getClosestVowel = (word) => {
  const vowels = new Set('aeiouAEIOU');

  // No possible vowel between two consonants if length < 3
  if (word.length < 3) return '';

  for (let i = word.length - 1; i >= 0; i--) {
    const ch = word[i];
    if (!vowels.has(ch)) continue;          // not a vowel

    // Skip vowels at the boundaries
    if (i === 0 || i === word.length - 1) continue;

    const left = word[i - 1];
    const right = word[i + 1];

    if (!vowels.has(left) && !vowels.has(right)) {
      return ch; // first such vowel from the right
    }
  }

  return ''; // no vowel satisfies the condition
};
