 * Determine whether two strings of parentheses can be concatenated
 * (in some order) to form a balanced string.
 *
 * @param {string[]} lst - Array of two strings containing only '(' and ')'.
 * @returns {string} 'Yes' if a balanced concatenation exists, otherwise 'No'.
 */
const matchParens = (lst) => {
  // Helper to compute net balance and minimal prefix balance of a string
  const analyze = (s) => {
    let balance = 0;
    let minBalance = 0;
    for (const ch of s) {
      if (ch === '(') {
        balance += 1;
      } else { // ')'
        balance -= 1;
      }
      if (balance < minBalance) minBalance = balance;
    }
    return { net: balance, min: minBalance };
  };

  const [s1, s2] = lst;
  const a = analyze(s1);
  const b = analyze(s2);

  const totalNet = a.net + b.net;
  if (totalNet !== 0) return 'No'; // overall balance must be zero

  // Check order s1 + s2
  if (a.min >= 0 && b.min + a.net >= 0) return 'Yes';

  // Check order s2 + s1
  if (b.min >= 0 && a.min + b.net >= 0) return 'Yes';

  return 'No';
};
