/**
 * Returns a sorted array of the k largest numbers from the input array.
 *
 * @param {number[]} arr - The input array of integers.
 * @param {number} k   - The number of maximum elements to return.
 * @returns {number[]} A new array containing the k largest numbers, sorted in ascending order.
 */
const maximum = (arr, k) => {
  if (k <= 0) return [];

  // Copy the array to avoid mutating the original
  const copy = arr.slice();

  // Sort in descending order to pick the largest k elements
  const topK = copy.sort((a, b) => b - a).slice(0, k);

  // Return the selected elements sorted in ascending order
  return topK.sort((a, b) => a - b);
};
