/**
 * Returns a sorted array of the odd numbers that appear in the Collatz sequence
 * starting from the given positive integer `n`.
 *
 * @param {number} n - A positive integer.
 * @returns {number[]} Sorted list of odd numbers from the Collatz sequence.
 */
const getOddCollatz = (n) => {
  if (n <= 0 || !Number.isInteger(n)) {
    throw new Error('Input must be a positive integer');
  }

  const sequence = [];
  let current = n;

  // Build the Collatz sequence until 1 is reached
  while (true) {
    sequence.push(current);
    if (current === 1) break;
    current = current % 2 === 0 ? current / 2 : 3 * current + 1;
  }

  // Extract odd numbers and sort them in ascending order
  return sequence
    .filter((value) => value % 2 === 1)
    .sort((a, b) => a - b);
};
```

