/**
 * Validates a date string in the format mm-dd-yyyy.
 *
 * Rules:
 * 1. The string must not be empty.
 * 2. The format must be exactly two digits for month, two digits for day,
 *    a hyphen separator, and four digits for year (mm-dd-yyyy).
 * 3. Month must be between 01 and 12.
 * 4. Day must be within the valid range for the given month:
 *    - 31 days for months 01,03,05,07,08,10,12
 *    - 30 days for months 04,06,09,11
 *    - 29 days for month 02 (no leap‑year logic required)
 *
 * @param {string} date - The date string to validate.
 * @returns {boolean} - true if the date is valid, false otherwise.
 */
const validDate = (date) => {
  // Rule 1: non‑empty string
  if (typeof date !== 'string' || date.trim() === '') return false;

  // Rule 2: strict format mm-dd-yyyy
  const formatRegex = /^\d{2}-\d{2}-\d{4}$/;
  if (!formatRegex.test(date)) return false;

  const [mmStr, ddStr, yyyyStr] = date.split('-');
  const month = Number(mmStr);
  const day   = Number(ddStr);
  const year  = Number(yyyyStr); // year is not validated beyond being 4 digits

  // Rule 3: month range
  if (month < 1 || month > 12) return false;

  // Rule 4: day range per month
  const maxDay = (() => {
    switch (month) {
      case 1: case 3: case 5: case 7: case 8: case 10: case 12:
        return 31;
      case 4: case 6: case 9: case 11:
        return 30;
      case 2:
        return 29; // no leap‑year logic required
      default:
        return 0; // unreachable, but keeps TypeScript happy
    }
  })();

  if (day < 1 || day > maxDay) return false;

  // All checks passed
  return true;
};
```

