/**
 * Count lower‑case letters with odd alphabetic index (a=0, b=1, …).
 * @param {string} str
 * @returns {number}
 */
const countOddLowercase = (str) => {
  let count = 0;
  for (const ch of str) {
    const code = ch.charCodeAt(0);
    if (code >= 97 && code <= 122) {          // 'a' to 'z'
      const idx = code - 97;                  // 0‑based index
      if (idx % 2 === 1) count++;              // odd index
    }
  }
  return count;
};

/**
 * Split a string into words based on whitespace or commas, or return
 * the count of lower‑case letters with odd alphabetic index if neither
 * separator is present.
 *
 * @param {string} txt
 * @returns {Array<string>|number}
 */
const splitWords = (txt) => {
  if (/\s/.test(txt)) {
    // Split on one or more whitespace characters
    return txt.trim().split(/\s+/);
  }

  if (txt.includes(',')) {
    // Split on commas
    return txt.split(',');
  }

  // No whitespace or commas – return the odd‑index lower‑case count
  return countOddLowercase(txt);
};
