const isSorted = (lst) => {
  if (!Array.isArray(lst) || lst.length <= 1) return true;

  let prev = lst[0];
  let dupCount = 0; // number of times the current value has been seen consecutively

  for (let i = 1; i < lst.length; i++) {
    const cur = lst[i];

    if (cur < prev) return false;          // not ascending

    if (cur === prev) {
      dupCount++;
      if (dupCount > 1) return false;      // more than one duplicate
    } else {
      // new value
      dupCount = 0;
      prev = cur;
    }
  }

  return true;
};
