/**
 * Returns the sum of magnitudes of the integers in `arr`
 * multiplied by the product of their signs (1, -1, or 0).
 * If `arr` is empty, returns null.
 *
 * @param {number[]} arr - Array of integers.
 * @returns {number|null} The computed value or null for an empty array.
 */
const prodSigns = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) return null;

  let sumAbs = 0;
  let productSign = 1;

  for (const num of arr) {
    sumAbs += Math.abs(num);

    if (num === 0) {
      productSign = 0;          // zero overrides all other signs
    } else if (num < 0 && productSign !== 0) {
      productSign *= -1;        // flip sign for each negative number
    }
  }

  return sumAbs * productSign;
};
