/**
 * Finds the lexicographically minimal path of length `k` in a grid.
 *
 * @param {number[][]} grid - An N x N grid containing a permutation of 1..N*N.
 * @param {number} k - Desired path length (number of cells visited).
 * @returns {number[]} The values of the cells along the minimal path.
 */
const minPath = (grid, k) => {
  const N = grid.length;
  if (N === 0 || k <= 0) return [];

  // Locate the cell containing the value 1 (the smallest possible start).
  let startRow = -1, startCol = -1;
  for (let r = 0; r < N; r++) {
    for (let c = 0; c < N; c++) {
      if (grid[r][c] === 1) {
        startRow = r;
        startCol = c;
        break;
      }
    }
    if (startRow !== -1) break;
  }

  // If 1 is not found (should not happen with valid input), return empty.
  if (startRow === -1) return [];

  const path = [1];
  let r = startRow, c = startCol;

  // Directions: up, down, left, right.
  const dirs = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  for (let step = 1; step < k; step++) {
    let minVal = Infinity;
    let nextR = r, nextC = c;

    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
        const val = grid[nr][nc];
        if (val < minVal) {
          minVal = val;
          nextR = nr;
          nextC = nc;
        }
      }
    }

    // Move to the neighbor with the smallest value.
    r = nextR;
    c = nextC;
    path.push(minVal);
  }

  return path;
};
