/**
 * Returns the first n + 1 terms of the Tribonacci sequence.
 *
 * The sequence is defined as:
 *   tri(0) = 1
 *   tri(1) = 3
 *   tri(n) = 1 + n / 2          if n is even
 *   tri(n) = tri(n‑1) + tri(n‑2) + tri(n+1)  if n is odd
 *
 * @param {number} n - non‑negative integer
 * @returns {number[]} array of length n + 1 containing tri(0)…tri(n)
 */
const tri = (n) => {
  const result = [];
  for (let i = 0; i <= n; i++) {
    if (i === 0) {
      result[i] = 1;
    } else if (i === 1) {
      result[i] = 3;
    } else if (i % 2 === 0) {
      result[i] = 1 + i / 2;
    } else {
      // For odd i, tri(i+1) is defined by the even rule
      const next = 1 + (i + 1) / 2;
      result[i] = result[i - 1] + result[i - 2] + next;
    }
  }
  return result;
};
```

