/**
 * Returns the lexicographically smallest path of length `k` in the given grid.
 *
 * @param {number[][]} grid - An N x N grid containing a permutation of 1..N*N.
 * @param {number} k - Desired path length (k >= 1).
 * @returns {number[]} The list of values along the minimal path.
 */
const minPath = (grid, k) => {
  const N = grid.length;
  if (k === 0) return [];

  // Find the unique cell containing value 1 (the smallest possible start).
  let startR = -1, startC = -1;
  for (let r = 0; r < N; r++) {
    for (let c = 0; c < N; c++) {
      if (grid[r][c] === 1) {
        startR = r;
        startC = c;
        break;
      }
    }
    if (startR !== -1) break;
  }

  // If k == 1, the answer is just [1].
  if (k === 1) return [1];

  const result = [1];
  let currentPositions = [[startR, startC]]; // positions that achieve current prefix

  const dirs = [
    [-1, 0], // up
    [1, 0],  // down
    [0, -1], // left
    [0, 1]   // right
  ];

  for (let step = 1; step < k; step++) {
    const neighborPositions = [];
    let minVal = Infinity;

    // Gather all neighbors of current positions and find minimal value.
    for (const [r, c] of currentPositions) {
      for (const [dr, dc] of dirs) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
          const val = grid[nr][nc];
          if (val < minVal) {
            minVal = val;
          }
          neighborPositions.push([nr, nc, val]); // store value for later filtering
        }
      }
    }

    result.push(minVal);

    // Keep only those neighbor positions that have the minimal value.
    const nextPositionsSet = new Set();
    const nextPositions = [];
    for (const [nr, nc, val] of neighborPositions) {
      if (val === minVal) {
        const key = nr * N + nc; // encode position to avoid duplicates
        if (!nextPositionsSet.has(key)) {
          nextPositionsSet.add(key);
          nextPositions.push([nr, nc]);
        }
      }
    }

    currentPositions = nextPositions;
  }

  return result;
};
