/**
 * Returns the first n + 1 numbers of the Tribonacci sequence.
 *
 * The sequence is defined as:
 *   tri(0) = 1
 *   tri(1) = 3
 *   tri(n) = 1 + n / 2          if n is even
 *   tri(n) = tri(n‑1) + tri(n‑2) + tri(n+1)  if n is odd
 *
 * For odd n, tri(n+1) is always even, so it can be computed directly.
 *
 * @param {number} n - Non‑negative integer.
 * @returns {number[]} Array of length n + 1 containing the sequence values.
 */
const tri = (n) => {
  if (n < 0) return [];

  const seq = [];

  for (let i = 0; i <= n; i++) {
    if (i === 0) {
      seq.push(1);
    } else if (i === 1) {
      seq.push(3);
    } else if (i % 2 === 0) {
      // Even index
      seq.push(1 + i / 2);
    } else {
      // Odd index: use tri(i‑1), tri(i‑2), and tri(i+1) (which is even)
      const nextEven = 1 + (i + 1) / 2; // tri(i+1)
      seq.push(seq[i - 1] + seq[i - 2] + nextEven);
    }
  }

  return seq;
};
