/**
 * Returns the first n + 1 terms of the Tribonacci sequence.
 *
 * Definition:
 *   tri(0) = 1
 *   tri(1) = 3
 *   tri(n) = 1 + n / 2          if n is even
 *   tri(n) = tri(n‑1) + tri(n‑2) + tri(n+1)  if n is odd
 *
 * @param {number} n - non‑negative integer
 * @returns {number[]} array of length n + 1 containing the sequence
 */
const tri = (n) => {
  const result = new Array(n + 1);

  if (n >= 0) result[0] = 1;
  if (n >= 1) result[1] = 3;

  for (let i = 2; i <= n; i++) {
    if (i % 2 === 0) {
      // Even index: direct formula
      result[i] = 1 + i / 2;
    } else {
      // Odd index: uses previous two terms and the next even term
      const nextEven = 1 + (i + 1) / 2; // tri(i+1) is even
      result[i] = result[i - 1] + result[i - 2] + nextEven;
    }
  }

  return result;
};
