/**
 * Returns the product of all odd digits in a positive integer.
 * If the number contains no odd digits, returns 0.
 *
 * @param {number} n - A positive integer.
 * @returns {number} The product of odd digits or 0 if none.
 */
const digits = (n) => {
  if (n < 0) n = -n;          // just in case a negative is passed
  let product = 1;
  let hasOdd = false;

  while (n > 0) {
    const digit = n % 10;
    if (digit % 2 === 1) {    // odd digit
      product *= digit;
      hasOdd = true;
    }
    n = Math.floor(n / 10);
  }

  return hasOdd ? product : 0;
};
```

