const tri = (n) => {
  const memo = new Map();

  const getTri = (k) => {
    if (memo.has(k)) return memo.get(k);

    let value;
    if (k === 0) {
      value = 1;                     // tri(0) is defined as 1
    } else if (k === 1) {
      value = 3;                     // tri(1) = 3
    } else if (k % 2 === 0) {
      value = 1 + k / 2;             // even case
    } else {
      // odd case: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
      value = getTri(k - 1) + getTri(k - 2) + getTri(k + 1);
    }

    memo.set(k, value);
    return value;
  };

  const result = [];
  for (let i = 0; i <= n; i++) {
    result.push(getTri(i));
  }
  return result;
};
