/**
 * Returns true if the input string of square brackets contains a valid
 * subsequence that is a balanced bracket sequence with at least one
 * nested pair. Otherwise returns false.
 *
 * @param {string} s - String consisting only of '[' and ']'.
 * @returns {boolean}
 */
const isNested = (s) => {
  const n = s.length;
  if (n < 4) return false; // need at least 4 brackets to form [ [ ] ]

  // prefixOpen[i] = number of '[' in s[0..i-1]
  const prefixOpen = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefixOpen[i + 1] = prefixOpen[i] + (s[i] === '[' ? 1 : 0);
  }

  // suffixClose[i] = number of ']' in s[i..n-1]
  const suffixClose = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    suffixClose[i] = suffixClose[i + 1] + (s[i] === ']' ? 1 : 0);
  }

  // Look for a '[' that has at least one '[' before it and at least two
  // ']' after it.
  for (let j = 0; j < n; j++) {
    if (s[j] !== '[') continue;
    if (prefixOpen[j] >= 1 && suffixClose[j + 1] >= 2) {
      return true;
    }
  }

  return false;
};
