/**
 * Returns true if the input string of '[' and ']' contains a valid
 * subsequence of brackets that has at least one nested pair.
 *
 * The idea is to find indices i < j < k < l such that
 *   s[i] = '['
 *   s[j] = '['
 *   s[k] = ']'
 *   s[l] = ']'
 * This guarantees a nested structure "[[...]]".
 *
 * We pre‑compute:
 *   - prefixOpenBefore[i]  : number of '[' before index i
 *   - suffixCloseAfter[i] : number of ']' after index i
 *
 * Then we scan for an index j where s[j] === '[',
 *   prefixOpenBefore[j] >= 1   (there is an earlier '[')
 *   suffixCloseAfter[j] >= 2   (there are at least two ']' after j)
 *
 * If such a j exists, a nested subsequence exists.
 */
const isNested = (str) => {
  const n = str.length;

  // prefixOpenBefore[i] = number of '[' before index i
  const prefixOpenBefore = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefixOpenBefore[i + 1] = prefixOpenBefore[i] + (str[i] === '[' ? 1 : 0);
  }

  // suffixCloseAfter[i] = number of ']' after index i
  const suffixCloseAfter = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    suffixCloseAfter[i] = suffixCloseAfter[i + 1] + (str[i] === ']' ? 1 : 0);
  }

  for (let j = 0; j < n; j++) {
    if (
      str[j] === '[' &&
      prefixOpenBefore[j] >= 1 &&          // at least one '[' before j
      suffixCloseAfter[j] >= 2            // at least two ']' after j
    ) {
      return true;
    }
  }

  return false;
};
