/**
 * Returns the largest index i such that arr[i] < arr[i-1].
 * If no such index exists, returns -1.
 *
 * @param {number[]} arr - Array of distinct numbers.
 * @returns {number} The largest qualifying index or -1.
 */
const canArrange = (arr) => {
  if (!Array.isArray(arr) || arr.length < 2) return -1;

  // Scan from the end to find the first index where the element is less than its predecessor.
  for (let i = arr.length - 1; i > 0; i--) {
    if (arr[i] < arr[i - 1]) return i;
  }

  return -1; // No such element found
};
