/**
 * Returns true if the last character of `txt` is an alphabetical letter
 * and is not part of a longer word (i.e., the preceding character is not a letter).
 * Otherwise returns false.
 *
 * @param {string} txt
 * @returns {boolean}
 */
const checkIfLastCharIsALetter = (txt) => {
  if (!txt || txt.length === 0) return false;

  const lastChar = txt[txt.length - 1];
  if (!isLetter(lastChar)) return false;

  // If there's only one character, it's not part of a word.
  if (txt.length === 1) return true;

  const prevChar = txt[txt.length - 2];
  return !isLetter(prevChar);
};

