/**
 * Computes the Brazilian factorial (special factorial) of a positive integer n.
 * The result is returned as a BigInt to avoid overflow for larger n.
 *
 * brazilian_factorial(n) = n! * (n-1)! * ... * 1!
 *
 * @param {number} n - A positive integer (n > 0)
 * @returns {BigInt} The special factorial of n
 */
const specialFactorial = (n) => {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('Input must be a positive integer.');
  }

  let factorial = 1n;   // current i!
  let result = 1n;      // product of all factorials

  for (let i = 1; i <= n; i++) {
    factorial *= BigInt(i); // compute i!
    result *= factorial;    // multiply into the running product
  }

  return result;
};
