/**
 * Checks whether a file name is valid according to the specified rules.
 *
 * @param {string} file_name - The file name to validate.
 * @returns {string} 'Yes' if the file name is valid, otherwise 'No'.
 */
const fileNameCheck = (file_name) => {
  // Rule 1: Exactly one dot
  const parts = file_name.split('.');
  if (parts.length !== 2) return 'No';

  const [name, ext] = parts;

  // Rule 2: Name part must not be empty and must start with a Latin letter
  if (!name || !/^[A-Za-z]/.test(name)) return 'No';

  // Rule 3: Extension must be one of the allowed types
  const allowedExts = new Set(['txt', 'exe', 'dll']);
  if (!allowedExts.has(ext)) return 'No';

  // Rule 4: No more than three digits in the entire file name
  const digitCount = (file_name.match(/[0-9]/g) || []).length;
  if (digitCount > 3) return 'No';

  return 'Yes';
};
```

