/**
 * Parse a fraction string "numerator/denominator" into BigInt components.
 * @param {string} frac
 * @returns {[BigInt, BigInt]} [numerator, denominator]
 */
const parseFraction = (frac) => {
  const [numStr, denStr] = frac.split('/');
  return [BigInt(numStr), BigInt(denStr)];
};

/**
 * Determine whether the product of two fractions is an integer.
 * @param {string} x - First fraction in the form "numerator/denominator".
 * @param {string} n - Second fraction in the form "numerator/denominator".
 * @returns {boolean} true if x * n is a whole number, false otherwise.
 */
const simplify = (x, n) => {
  const [xNum, xDen] = parseFraction(x);
  const [nNum, nDen] = parseFraction(n);

  // product = (xNum * nNum) / (xDen * nDen)
  const numerator = xNum * nNum;
  const denominator = xDen * nDen;

  return numerator % denominator === 0n;
};
