/**
 * Returns the sum of the decimal digits of a number (ignoring its sign).
 * @param {number} n
 * @returns {number}
 */
const digitSum = (n) => {
  const absStr = Math.abs(n).toString();
  return absStr.split('').reduce((sum, ch) => sum + Number(ch), 0);
};

/**
 * Sorts an array of integers in ascending order according to the sum of their digits.
 * If two numbers have the same digit sum, the one that appeared later in the original
 * array comes first (i.e., original index descending).
 *
 * @param {number[]} nums
 * @returns {number[]}
 */
const orderByPoints = (nums) => {
  if (!Array.isArray(nums) || nums.length === 0) return [];

  // Attach metadata: value, digit sum, original index
  const withMeta = nums.map((value, idx) => ({
    value,
    sum: digitSum(value),
    idx,
  }));

  // Sort by sum ascending, then by original index descending
  withMeta.sort((a, b) => {
    if (a.sum !== b.sum) return a.sum - b.sum;
    return b.idx - a.idx; // later index first
  });

  // Extract sorted values
  return withMeta.map(item => item.value);
};
