/**
 * Returns the number of elements in the array that are greater than 10
 * and whose first and last digits are odd (1, 3, 5, 7, 9).
 *
 * @param {number[]} nums - Array of numbers to filter.
 * @returns {number} Count of qualifying numbers.
 */
const specialFilter = (nums) => {
  const isOddDigit = (digit) => digit % 2 === 1;

  let count = 0;

  for (const num of nums) {
    if (num > 10) {
      const str = Math.abs(num).toString(); // ignore sign
      const firstDigit = parseInt(str[0], 10);
      const lastDigit = parseInt(str[str.length - 1], 10);

      if (isOddDigit(firstDigit) && isOddDigit(lastDigit)) {
        count++;
      }
    }
  }

  return count;
};
