/**
 * Counts how many numbers in the array are greater than 10
 * and have both first and last digits odd.
 *
 * @param {number[]} nums - Array of numbers to evaluate.
 * @returns {number} The count of qualifying numbers.
 */
const specialFilter = (nums) => {
  let count = 0;

  for (const n of nums) {
    if (n > 10) {
      const abs = Math.abs(n);

      // Last digit
      const last = abs % 10;
      if (last % 2 !== 1) continue; // not odd

      // First digit
      let first = abs;
      while (first >= 10) {
        first = Math.floor(first / 10);
      }
      if (first % 2 !== 1) continue; // not odd

      count++;
    }
  }

  return count;
};
