const bf = (planet1, planet2) => {
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune"
  ];

  const idx1 = planets.indexOf(planet1);
  const idx2 = planets.indexOf(planet2);

  // If either planet is not found, return an empty tuple (array)
  if (idx1 === -1 || idx2 === -1) return [];

  // Determine the range between the two planets (exclusive)
  const start = Math.min(idx1, idx2) + 1;
  const end   = Math.max(idx1, idx2);

  // If there are no planets between them, return an empty tuple
  if (start >= end) return [];

  // Slice the array to get the planets between them
  return planets.slice(start, end);
};
```

