/**
 * Removes strings with odd lengths from the input list and returns the
 * remaining strings sorted first by ascending length and then alphabetically
 * for strings of equal length.
 *
 * @param {string[]} lst - The list of strings to process.
 * @returns {string[]} A new list containing only even‑length strings,
 *                     sorted by the specified rules.
 */
const sortedListSum = (lst) => {
  // Filter out strings with odd lengths
  const evenLengthStrings = lst.filter(str => str.length % 2 === 0);

  // Sort by length ascending, then alphabetically for equal lengths
  evenLengthStrings.sort((a, b) => {
    const lenDiff = a.length - b.length;
    if (lenDiff !== 0) return lenDiff;
    return a.localeCompare(b);
  });

  return evenLengthStrings;
};
