/**
 * Returns a new list containing only the strings with even length,
 * sorted first by ascending length and then alphabetically for ties.
 *
 * @param {string[]} lst - The input list of strings.
 * @returns {string[]} A sorted list of strings with even lengths.
 */
const sortedListSum = (lst) => {
  // Helper to check if a string has an even length
  const isEvenLength = (str) => str.length % 2 === 0;

  // Filter out strings with odd lengths
  const evenStrings = lst.filter(isEvenLength);

  // Sort by length, then alphabetically
  evenStrings.sort((a, b) => {
    if (a.length !== b.length) {
      return a.length - b.length; // ascending length
    }
    return a.localeCompare(b); // alphabetical for equal length
  });

  return evenStrings;
};
