/**
 * Computes the strength of an extension name.
 * Strength = (# of uppercase letters) - (# of lowercase letters)
 *
 * @param {string} ext - The extension name.
 * @returns {number} The strength value.
 */
const extensionStrength = (ext) => {
  let upper = 0;
  let lower = 0;
  for (let i = 0; i < ext.length; i++) {
    const ch = ext[i];
    if (ch >= 'A' && ch <= 'Z') upper++;
    else if (ch >= 'a' && ch <= 'z') lower++;
  }
  return upper - lower;
};

/**
 * Finds the strongest extension for a given class name.
 *
 * @param {string} class_name - The base class name.
 * @param {string[]} extensions - Array of extension names.
 * @returns {string} The combined string "ClassName.StrongestExtensionName".
 */
const strongestExtension = (class_name, extensions) => {
  let bestIdx = 0;
  let bestStrength = extensionStrength(extensions[0]);

  for (let i = 1; i < extensions.length; i++) {
    const strength = extensionStrength(extensions[i]);
    if (strength > bestStrength) {
      bestStrength = strength;
      bestIdx = i;
    }
  }

  return `${class_name}.${extensions[bestIdx]}`;
};
