/**
 * Returns true if the second word `b` or any of its rotations
 * appears as a substring in the first word `a`.
 *
 * @param {string} a - The string to search within.
 * @param {string} b - The string whose rotations are to be searched.
 * @returns {boolean}
 */
const cycpatternCheck = (a, b) => {
  if (!b) return true; // empty string is always a substring

  const len = b.length;
  for (let i = 0; i < len; i++) {
    const rotation = b.slice(i) + b.slice(0, i);
    if (a.includes(rotation)) return true;
  }
  return false;
};
