 * Returns true if the second word or any of its rotations
 * appears as a substring in the first word.
 *
 * @param {string} a - The string to search within.
 * @param {string} b - The string to rotate and search for.
 * @returns {boolean}
 */
const cycpatternCheck = (a, b) => {
  // If b is longer than a, it can never be a substring.
  if (b.length > a.length) return false;

  // Concatenate b with itself; every rotation of b is a substring of this.
  const doubleB = b + b;

  // Check each rotation of b.
  for (let i = 0; i < b.length; i++) {
    const rotation = doubleB.slice(i, i + b.length);
    if (a.includes(rotation)) return true;
  }

  return false;
};
