/**
 * Returns true if the input string of square brackets contains a valid
 * subsequence that is a balanced bracket sequence with at least one nested pair.
 *
 * A nested pair exists when we can pick indices i < j < k < l such that
 * s[i] = '[' , s[j] = '[' , s[k] = ']' , s[l] = ']'.
 * This guarantees a subsequence "[[...]]" which is a valid nested structure.
 *
 * @param {string} str - String consisting only of '[' and ']'.
 * @returns {boolean}
 */
const isNested = (str) => {
  const n = str.length;
  if (n < 4) return false; // need at least two pairs

  // Find the first two '['
  let firstOpen = -1, secondOpen = -1;
  for (let i = 0; i < n; i++) {
    if (str[i] === '[') {
      if (firstOpen === -1) firstOpen = i;
      else if (secondOpen === -1) {
        secondOpen = i;
        break;
      }
    }
  }
  if (secondOpen === -1) return false; // less than two '['

  // Find the first two ']' after the second '['
  let firstClose = -1, secondClose = -1;
  for (let i = secondOpen + 1; i < n; i++) {
    if (str[i] === ']') {
      if (firstClose === -1) firstClose = i;
      else {
        secondClose = i;
        break;
      }
    }
  }
  return secondClose !== -1;
};
```

