/**
 * Counts the even and odd digits in an integer.
 *
 * @param {number} num - The integer to analyze.
 * @returns {[number, number]} A tuple where the first element is the count of even digits
 *                            and the second element is the count of odd digits.
 */
const evenOddCount = (num) => {
  // Work with the absolute value to ignore a leading minus sign
  const digits = Math.abs(num).toString();

  let even = 0;
  let odd = 0;

  for (const ch of digits) {
    // Convert the character to its numeric value
    const digit = ch.charCodeAt(0) - 48; // '0'.charCodeAt(0) === 48
    if (digit % 2 === 0) {
      even++;
    } else {
      odd++;
    }
  }

  return [even, odd];
};
