const intToMiniRoman = (number) => {
  const romanMap = [
    { value: 1000, symbol: 'm' },
    { value: 900,  symbol: 'cm' },
    { value: 500,  symbol: 'd' },
    { value: 400,  symbol: 'cd' },
    { value: 100,  symbol: 'c' },
    { value: 90,   symbol: 'xc' },
    { value: 50,   symbol: 'l' },
    { value: 40,   symbol: 'xl' },
    { value: 10,   symbol: 'x' },
    { value: 9,    symbol: 'ix' },
    { value: 5,    symbol: 'v' },
    { value: 4,    symbol: 'iv' },
    { value: 1,    symbol: 'i' }
  ];

  let result = '';
  for (const { value, symbol } of romanMap) {
    while (number >= value) {
      result += symbol;
      number -= value;
    }
  }
  return result;
};
