const rightAngleTriangle = (a, b, c) => {
  // All sides must be positive numbers
  if (a <= 0 || b <= 0 || c <= 0) return false;

  // Triangle inequality: sum of any two sides must be greater than the third
  if (a + b <= c || a + c <= b || b + c <= a) return false;

  // Sort the sides so that the largest side is last
  const sides = [a, b, c].sort((x, y) => x - y);
  const [x, y, z] = sides; // z is the longest side

  // Check the Pythagorean theorem with a tolerance for floating‑point errors
  const lhs = z * z;
  const rhs = x * x + y * y;
  const epsilon = Number.EPSILON * Math.max(lhs, rhs, 1);

  return Math.abs(lhs - rhs) <= epsilon;
};
```

