/**
 * Checks whether three side lengths can form a right‑angled triangle.
 *
 * @param {number} a - Length of side a.
 * @param {number} b - Length of side b.
 * @param {number} c - Length of side c.
 * @returns {boolean} true if the sides form a right‑angled triangle, false otherwise.
 */
const rightAngleTriangle = (a, b, c) => {
  // Basic validation: all sides must be positive numbers
  if (![a, b, c].every(side => typeof side === 'number' && side > 0)) {
    return false;
  }

  // Triangle inequality check
  if (a + b <= c || a + c <= b || b + c <= a) {
    return false;
  }

  // Sort sides so that z is the largest (hypotenuse candidate)
  const [x, y, z] = [a, b, c].sort((p, q) => p - q);

  // Use a tolerance to account for floating‑point arithmetic
  const tolerance = 1e-10;
  return Math.abs(x * x + y * y - z * z) < tolerance;
};
```

