/**
 * Convert a positive integer (1 ≤ number ≤ 1000) to its Roman numeral representation.
 * The result is returned in lowercase.
 *
 * @param {number} number - The integer to convert.
 * @returns {string} The Roman numeral string in lowercase.
 */
const intToMiniRoman = (number) => {
  if (typeof number !== 'number' || number < 1 || number > 1000) {
    throw new RangeError('Input must be an integer between 1 and 1000 inclusive.');
  }

  // Mapping of integer values to Roman numeral symbols (lowercase).
  const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  const symbols = ['m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'];

  let result = '';
  let remaining = number;

  for (let i = 0; i < values.length; i++) {
    while (remaining >= values[i]) {
      remaining -= values[i];
      result += symbols[i];
    }
  }

  return result;
};
