/**
 * Calculates the total carrots eaten and the remaining carrots after a rabbit's meal.
 *
 * @param {number} number   - Carrots already eaten.
 * @param {number} need     - Carrots the rabbit wants to eat.
 * @param {number} remaining - Carrots available in stock.
 * @returns {[number, number]} - [total eaten, remaining left]
 */
const eat = (number, need, remaining) => {
  // Determine how many carrots the rabbit can actually eat
  const eaten = Math.min(need, remaining);

  // Total carrots eaten after this meal
  const totalEaten = number + eaten;

  // Carrots left after the meal
  const left = remaining - eaten;

  return [totalEaten, left];
};
```

