const solve = (s) => {
  // Helper to check if a character is a letter
  const isLetter = (ch) => {
    const code = ch.charCodeAt(0);
    return (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
  };

  // Determine if the string contains any letters
  let hasLetter = false;
  for (let i = 0; i < s.length; i++) {
    if (isLetter(s[i])) {
      hasLetter = true;
      break;
    }
  }

  if (hasLetter) {
    // Reverse case for each letter
    return s
      .split('')
      .map((ch) => {
        if (ch >= 'a' && ch <= 'z') return ch.toUpperCase();
        if (ch >= 'A' && ch <= 'Z') return ch.toLowerCase();
        return ch;
      })
      .join('');
  } else {
    // No letters: reverse the whole string
    return s.split('').reverse().join('');
  }
