/**
 * Evaluate an algebraic expression defined by two parallel lists:
 *   - operator: array of operators ('+', '-', '*', '//', '**')
 *   - operand:  array of non‑negative integers
 *
 * The expression is evaluated following standard arithmetic precedence:
 *   1. '**' (right‑associative)
 *   2. '*', '//'
 *   3. '+', '-'
 *
 * @param {string[]} operator - list of operators
 * @param {number[]} operand  - list of operands
 * @returns {number} The evaluated result
 */
const doAlgebra = (operator, operand) => {
  // ---------- Helper: Shunting‑yard to convert to RPN ----------
  const precedence = {
    '+': 1,
    '-': 1,
    '*': 2,
    '//': 2,
    '**': 3,
  };
  const rightAssociative = new Set(['**']);

  const toRPN = (ops, vals) => {
    const output = [];
    const opStack = [];

    const pushVal = (v) => output.push(v);
    const pushOp = (o) => {
      while (opStack.length) {
        const top = opStack[opStack.length - 1];
        const topPrec = precedence[top];
        const curPrec = precedence[o];
        if (
          (rightAssociative.has(o) && curPrec < topPrec) ||
          (!rightAssociative.has(o) && curPrec <= topPrec)
        ) {
          output.push(opStack.pop());
        } else {
          break;
        }
      }
      opStack.push(o);
    };

    // Interleave operands and operators
    for (let i = 0; i < vals.length; i++) {
      pushVal(vals[i]);          // operand
      if (i < ops.length) {
        pushOp(ops[i]);          // operator
      }
    }

    // Drain remaining operators
    while (opStack.length) {
      output.push(opStack.pop());
    }

    return output;
  };

  // ---------- Helper: Evaluate RPN ----------
  const evalRPN = (tokens) => {
    const stack = [];
    for (const token of tokens) {
      if (typeof token === 'number') {
        stack.push(token);
      } else {
        const right = stack.pop();
        const left = stack.pop();
        let res;
        switch (token) {
          case '+':
            res = left + right;
            break;
          case '-':
            res = left - right;
            break;
          case '*':
            res = left * right;
            break;
          case '//':
            res = Math.floor(left / right);
            break;
          case '**':
            res = Math.pow(left, right);
            break;
          default:
            throw new Error(`Unknown operator: ${token}`);
        }
        stack.push(res);
      }
    }
    return stack[0];
  };

  // Build RPN and evaluate
  const rpn = toRPN(operator, operand);
  return evalRPN(rpn);
};
