/**
 * Evaluate an algebraic expression defined by two parallel lists:
 *   - operator: array of operators ('+', '-', '*', '//', '**')
 *   - operand:  array of non‑negative integers
 *
 * The expression is built as:
 *   operand[0] operator[0] operand[1] operator[1] operand[2] ...
 *
 * Operator precedence follows standard arithmetic rules:
 *   ** (right‑associative) > * and // (left‑associative) > + and - (left‑associative)
 *
 * @param {string[]} operator - list of operators
 * @param {number[]} operand  - list of operands
 * @returns {number} The evaluated result
 */
const doAlgebra = (operator, operand) => {
  // Helper: precedence table
  const precedence = (op) => {
    switch (op) {
      case '**': return 4;
      case '*':
      case '//': return 3;
      case '+':
      case '-': return 2;
      default:  return 0;
    }
  };

  // Helper: associativity
  const isLeftAssociative = (op) => op !== '**';

  // Build token list: [num, op, num, op, ...]
  const tokens = [];
  for (let i = 0; i < operand.length; i++) {
    tokens.push(operand[i]);
    if (i < operator.length) tokens.push(operator[i]);
  }

  // Shunting‑yard algorithm: convert to Reverse Polish Notation (RPN)
  const outputQueue = [];
  const operatorStack = [];

  tokens.forEach((token) => {
    if (typeof token === 'number') {
      outputQueue.push(token);
    } else { // operator
      while (
        operatorStack.length &&
        typeof operatorStack[operatorStack.length - 1] === 'string' &&
        (
          (isLeftAssociative(token) && precedence(token) <= precedence(operatorStack[operatorStack.length - 1])) ||
          (!isLeftAssociative(token) && precedence(token) < precedence(operatorStack[operatorStack.length - 1]))
        )
      ) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    }
  });

  while (operatorStack.length) {
    outputQueue.push(operatorStack.pop());
  }

  // Evaluate RPN
  const evalStack = [];
  outputQueue.forEach((token) => {
    if (typeof token === 'number') {
      evalStack.push(token);
    } else {
      const right = evalStack.pop();
      const left  = evalStack.pop();
      let result;
      switch (token) {
        case '+': result = left + right; break;
        case '-': result = left - right; break;
        case '*': result = left * right; break;
        case '//': result = Math.floor(left / right); break;
        case '**': result = Math.pow(left, right); break;
        default: throw new Error(`Unsupported operator: ${token}`);
      }
      evalStack.push(result);
    }
  });

  return evalStack[0];
};
