      case '**': return 4;
      case '*':
      case '//': return 3;
      case '+':
      case '-': return 2;
      default:  return 0;
    }
  };

  const applyOp = (a, b, op) => {
    switch (op) {
      case '+': return a + b;
      case '-': return a - b;
      case '*': return a * b;
      case '//': return Math.floor(a / b);
      case '**': return Math.pow(a, b);
      default: throw new Error(`Unsupported operator: ${op}`);
    }
  };

  // ---------- Shunting‑yard algorithm ----------
  const outputQueue = [];
  const operatorStack = [];

