/**
 * Returns all even integers between a and b (inclusive) in ascending order.
 *
 * @param {number} a - First positive integer.
 * @param {number} b - Second positive integer.
 * @returns {number[]} Array of even integers between a and b, sorted ascending.
 */
const generateIntegers = (a, b) => {
  // Ensure a and b are integers and positive
  const start = Math.max(1, Math.min(a, b));
  const end   = Math.max(a, b);

  const evens = [];
  for (let n = start; n <= end; n++) {
    if (n % 2 === 0) evens.push(n);
  }
  return evens;
};
