/**
 * Returns the MD5 hash of the given string.
 * If the input is an empty string, null is returned.
 *
 * @param {string} text - The string to hash.
 * @returns {string|null} The MD5 hash in hexadecimal form, or null for an empty string.
 */
const stringToMd5 = (text) => {
  // Return null for an empty string
  if (text === '') return null;

  // Node.js crypto module
  const crypto = typeof require !== 'undefined' ? require('crypto') : null;
  if (!crypto) {
    throw new Error('MD5 hash requires the Node.js crypto module.');
  }

  return crypto.createHash('md5').update(text, 'utf8').digest('hex');
};
